import { describe, expect, test, xtest } from '@jest/globals';
import { decode, encode } from './affine-cipher';

describe('Affine cipher', () => {
  describe('encode', () => {
    test('encode yes', () => {
      expect(encode('yes', { a: 5, b: 7 })).toBe('xbt');
    });

    xtest('encode no', () => {
      expect(encode('no', { a: 15, b: 18 })).toBe('fu');
    });

    xtest('encode OMG', () => {
      expect(encode('OMG', { a: 21, b: 3 })).toBe('lvz');
    });

    xtest('encode O M G', () => {
      expect(encode('O M G', { a: 25, b: 47 })).toBe('hjp');
    });

    xtest('encode mindblowingly', () => {
      expect(encode('mindblowingly', { a: 11, b: 15 })).toBe('rzcwa gnxzc dgt');
    });

    xtest('encode numbers', () => {
      expect(encode('Testing,1 2 3, testing.', { a: 3, b: 4 })).toBe(
        'jqgjc rw123 jqgjc rw',
      );
    });

    xtest('encode deep thought', () => {
      expect(encode('Truth is fiction.', { a: 5, b: 17 })).toBe(
        'iynia fdqfb ifje',
      );
    });

    xtest('encode all the letters', () => {
      expect(
        encode('The quick brown fox jumps over the lazy dog.', {
          a: 17,
          b: 33,
        }),
      ).toBe('swxtj npvyk lruol iejdc blaxk swxmh qzglf');
    });

    xtest('encode with a not coprime to m', () => {
      expect(() => {
        encode('This is a test.', { a: 6, b: 17 });
      }).toThrow('a and m must be coprime.');
    });
  });
  describe('decode', () => {
    test('decode exercism', () => {
      expect(decode('tytgn fjr', { a: 3, b: 7 })).toBe('exercism');
    });

    xtest('decode a sentence', () => {
      expect(
        decode('qdwju nqcro muwhn odqun oppmd aunwd o', { a: 19, b: 16 }),
      ).toBe('anobstacleisoftenasteppingstone');
    });

    xtest('decode numbers', () => {
      expect(decode('odpoz ub123 odpoz ub', { a: 25, b: 7 })).toBe(
        'testing123testing',
      );
    });

    xtest('decode all the letters', () => {
      expect(
        decode('swxtj npvyk lruol iejdc blaxk swxmh qzglf', { a: 17, b: 33 }),
      ).toBe('thequickbrownfoxjumpsoverthelazydog');
    });

    xtest('decode with no spaces in input', () => {
      expect(
        decode('swxtjnpvyklruoliejdcblaxkswxmhqzglf', { a: 17, b: 33 }),
      ).toBe('thequickbrownfoxjumpsoverthelazydog');
    });

    xtest('decode with too many spaces', () => {
      expect(decode('vszzm    cly   yd cg    qdp', { a: 15, b: 16 })).toBe(
        'jollygreengiant',
      );
    });

    xtest('decode with a not coprime to m', () => {
      expect(() => {
        decode('Test', { a: 13, b: 5 });
      }).toThrow('a and m must be coprime.');
    });
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { convert } from './all-your-base';

describe('Converter', () => {
  test('single bit one to decimal', () => {
    expect(convert([1], 2, 10)).toEqual([1]);
  });

  xtest('binary to single decimal', () => {
    expect(convert([1, 0, 1], 2, 10)).toEqual([5]);
  });

  xtest('single decimal to binary', () => {
    expect(convert([5], 10, 2)).toEqual([1, 0, 1]);
  });

  xtest('binary to multiple decimal', () => {
    expect(convert([1, 0, 1, 0, 1, 0], 2, 10)).toEqual([4, 2]);
  });

  xtest('decimal to binary', () => {
    expect(convert([4, 2], 10, 2)).toEqual([1, 0, 1, 0, 1, 0]);
  });

  xtest('trinary to hexadecimal', () => {
    expect(convert([1, 1, 2, 0], 3, 16)).toEqual([2, 10]);
  });

  xtest('hexadecimal to trinary', () => {
    expect(convert([2, 10], 16, 3)).toEqual([1, 1, 2, 0]);
  });

  xtest('15-bit integer', () => {
    expect(convert([3, 46, 60], 97, 73)).toEqual([6, 10, 45]);
  });

  xtest('empty list', () => {
    expect(() => {
      convert([], 2, 10);
    }).toThrow(new Error('Input has wrong format'));
  });

  xtest('single zero', () => {
    expect(convert([0], 10, 2)).toEqual([0]);
  });

  xtest('multiple zeros', () => {
    expect(() => {
      convert([0, 0, 0], 10, 2);
    }).toThrow(new Error('Input has wrong format'));
  });

  xtest('leading zeros', () => {
    expect(() => {
      convert([0, 6, 0], 7, 10);
    }).toThrow(new Error('Input has wrong format'));
  });

  xtest('negative digit', () => {
    expect(() => {
      convert([1, -1, 1, 0, 1, 0], 2, 10);
    }).toThrow(new Error('Input has wrong format'));
  });

  xtest('invalid positive digit', () => {
    expect(() => {
      convert([1, 2, 1, 0, 1, 0], 2, 10);
    }).toThrow(new Error('Input has wrong format'));
  });

  xtest('first base is one', () => {
    expect(() => {
      convert([], 1, 10);
    }).toThrow(new Error('Wrong input base'));
  });

  xtest('second base is one', () => {
    expect(() => {
      convert([1, 0, 1, 0, 1, 0], 2, 1);
    }).toThrow(new Error('Wrong output base'));
  });

  xtest('first base is zero', () => {
    expect(() => {
      convert([], 0, 10);
    }).toThrow(new Error('Wrong input base'));
  });

  xtest('second base is zero', () => {
    expect(() => {
      convert([7], 10, 0);
    }).toThrow(new Error('Wrong output base'));
  });

  xtest('first base is negative', () => {
    expect(() => {
      convert([1], -2, 10);
    }).toThrow(new Error('Wrong input base'));
  });

  xtest('second base is negative', () => {
    expect(() => {
      convert([1], 2, -7);
    }).toThrow(new Error('Wrong output base'));
  });

  xtest('both bases are negative', () => {
    expect(() => {
      convert([1], -2, -7);
    }).toThrow(new Error('Wrong input base'));
  });
});

