import { describe, expect, test, xtest } from '@jest/globals';
import { Change } from './change';

describe('Change', () => {
  test('change for 1 cent', () => {
    const change = new Change();
    const result = change.calculate([1, 5, 10, 25], 1);
    expect(result).toEqual([1]);
  });

  xtest('single coin change', () => {
    const change = new Change();
    const result = change.calculate([1, 5, 10, 25, 100], 25);
    expect(result).toEqual([25]);
  });

  xtest('multiple coin change', () => {
    const change = new Change();
    const result = change.calculate([1, 5, 10, 25, 100], 15);
    expect(result).toEqual([5, 10]);
  });

  xtest('change with Lilliputian Coins', () => {
    // https://en.wikipedia.org/wiki/Change-making_problem#Greedy_method
    const change = new Change();
    const result = change.calculate([1, 4, 15, 20, 50], 23);
    expect(result).toEqual([4, 4, 15]);
  });

  xtest('change with Lower Elbonia Coins', () => {
    // https://en.wikipedia.org/wiki/Change-making_problem#Greedy_method
    const change = new Change();
    const result = change.calculate([1, 5, 10, 21, 25], 63);
    expect(result).toEqual([21, 21, 21]);
  });

  xtest('large target values', () => {
    const change = new Change();
    const result = change.calculate([1, 2, 5, 10, 20, 50, 100], 999);
    expect(result).toEqual([
      2, 2, 5, 20, 20, 50, 100, 100, 100, 100, 100, 100, 100, 100, 100,
    ]);
  });

  xtest('possible change without unit coins available', () => {
    const change = new Change();
    const result = change.calculate([2, 5, 10, 20, 50], 21);
    expect(result).toEqual([2, 2, 2, 5, 10]);
  });

  xtest('another possible change without unit coins available', () => {
    const change = new Change();
    const result = change.calculate([4, 5], 27);
    expect(result).toEqual([4, 4, 4, 5, 5, 5]);
  });

  xtest('a greedy approach is not optimal', () => {
    const change = new Change();
    const result = change.calculate([1, 10, 11], 20);
    expect(result).toEqual([10, 10]);
  });

  xtest('no coins make 0 change', () => {
    const change = new Change();
    const result = change.calculate([1, 5, 10, 21, 25], 0);
    expect(result).toEqual([]);
  });

  xtest('error testing for change smaller than the smallest of coins', () => {
    const change = new Change();
    const message = 'The total 3 cannot be represented in the given currency.';
    const expectation = () => {
      change.calculate([5, 10], 3);
    };
    expect(expectation).toThrow(message);
  });

  xtest('error testing if no combination can add up to target', () => {
    const change = new Change();
    const message = 'The total 94 cannot be represented in the given currency.';
    const expectation = () => {
      change.calculate([5, 10], 94);
    };
    expect(expectation).toThrow(message);
  });

  xtest('cannot find negative change values', () => {
    const change = new Change();
    const message = 'Negative totals are not allowed.';
    const expectation = () => {
      change.calculate([1, 2, 5], -5);
    };
    expect(expectation).toThrow(message);
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import CircularBuffer, {
  BufferEmptyError,
  BufferFullError,
} from './circular-buffer';

describe('CircularBuffer', () => {
  test('reading empty buffer should fail', () => {
    const buffer = new CircularBuffer(1);
    expect(() => buffer.read()).toThrow(BufferEmptyError);
  });

  xtest('can read an item just written', () => {
    const buffer = new CircularBuffer(1);
    buffer.write('1');
    expect(buffer.read()).toBe('1');
  });

  xtest('each item may only be read once', () => {
    const buffer = new CircularBuffer(1);
    buffer.write('1');
    expect(buffer.read()).toBe('1');
    expect(() => buffer.read()).toThrow(BufferEmptyError);
  });

  xtest('items are read in the order they are written', () => {
    const buffer = new CircularBuffer(2);
    buffer.write('1');
    buffer.write('2');
    expect(buffer.read()).toBe('1');
    expect(buffer.read()).toBe('2');
  });

  xtest("full buffer can't be written to", () => {
    const buffer = new CircularBuffer(1);
    buffer.write('1');
    expect(() => buffer.write(2)).toThrow(BufferFullError);
  });

  xtest('a read frees up capacity for another write', () => {
    const buffer = new CircularBuffer(1);
    buffer.write('1');
    expect(buffer.read()).toBe('1');
    buffer.write('2');
    expect(buffer.read()).toBe('2');
  });

  xtest('read position is maintained even across multiple writes', () => {
    const buffer = new CircularBuffer(3);
    buffer.write('1');
    buffer.write('2');
    expect(buffer.read()).toBe('1');
    buffer.write('3');
    expect(buffer.read()).toBe('2');
    expect(buffer.read()).toBe('3');
  });

  xtest("items cleared out of buffer can't be read", () => {
    const buffer = new CircularBuffer(1);
    buffer.write('1');
    buffer.clear();
    expect(() => buffer.read()).toThrow(BufferEmptyError);
  });

  xtest('clear frees up capacity for another write', () => {
    const buffer = new CircularBuffer(1);
    buffer.write('1');
    buffer.clear();
    buffer.write('2');
    expect(buffer.read()).toBe('2');
  });

  xtest('clear does nothing on empty buffer', () => {
    const buffer = new CircularBuffer(1);
    buffer.clear();
    buffer.write('1');
    expect(buffer.read()).toBe('1');
  });

  xtest('forceWrite acts like write on non-full buffer', () => {
    const buffer = new CircularBuffer(2);
    buffer.write('1');
    buffer.forceWrite('2');
    expect(buffer.read()).toBe('1');
    expect(buffer.read()).toBe('2');
  });

  xtest('forceWrite replaces the oldest item on full buffer', () => {
    const buffer = new CircularBuffer(2);
    buffer.write('1');
    buffer.write('2');
    buffer.forceWrite('3');
    expect(buffer.read()).toBe('2');
    expect(buffer.read()).toBe('3');
  });

  xtest('forceWrite replaces the oldest item remaining in buffer following a read', () => {
    const buffer = new CircularBuffer(3);
    buffer.write('1');
    buffer.write('2');
    buffer.write('3');
    expect(buffer.read()).toBe('1');
    buffer.write('4');
    buffer.forceWrite('5');
    expect(buffer.read()).toBe('3');
    expect(buffer.read()).toBe('4');
    expect(buffer.read()).toBe('5');
  });

  xtest('initial clear does not affect wrapping around', () => {
    const buffer = new CircularBuffer(2);
    buffer.clear();
    buffer.write('1');
    buffer.write('2');
    buffer.forceWrite('3');
    buffer.forceWrite('4');
    expect(buffer.read()).toBe('3');
    expect(buffer.read()).toBe('4');
    expect(() => buffer.read()).toThrow(BufferEmptyError);
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { Clock } from './clock';

describe('Clock', () => {
  describe('Creating a new clock with an initial time', () => {
    test('on the hour', () => {
      expect(new Clock(8).toString()).toEqual('08:00');
    });

    xtest('past the hour', () => {
      expect(new Clock(11, 9).toString()).toEqual('11:09');
    });

    xtest('midnight is zero hours', () => {
      expect(new Clock(24, 0).toString()).toEqual('00:00');
    });

    xtest('hour rolls over', () => {
      expect(new Clock(25, 0).toString()).toEqual('01:00');
    });

    xtest('hour rolls over continuously', () => {
      expect(new Clock(100, 0).toString()).toEqual('04:00');
    });

    xtest('sixty minutes is next hour', () => {
      expect(new Clock(1, 60).toString()).toEqual('02:00');
    });

    xtest('minutes roll over', () => {
      expect(new Clock(0, 160).toString()).toEqual('02:40');
    });

    xtest('minutes roll over continuously', () => {
      expect(new Clock(0, 1723).toString()).toEqual('04:43');
    });

    xtest('hour and minutes roll over', () => {
      expect(new Clock(25, 160).toString()).toEqual('03:40');
    });

    xtest('hour and minutes roll over continuously', () => {
      expect(new Clock(201, 3001).toString()).toEqual('11:01');
    });

    xtest('hour and minutes roll over to exactly midnight', () => {
      expect(new Clock(72, 8640).toString()).toEqual('00:00');
    });

    xtest('negative hour', () => {
      expect(new Clock(-1, 15).toString()).toEqual('23:15');
    });

    xtest('negative hour rolls over', () => {
      expect(new Clock(-25, 0).toString()).toEqual('23:00');
    });

    xtest('negative hour rolls over continuously', () => {
      expect(new Clock(-91, 0).toString()).toEqual('05:00');
    });

    xtest('negative minutes', () => {
      expect(new Clock(1, -40).toString()).toEqual('00:20');
    });

    xtest('negative minutes rolls over', () => {
      expect(new Clock(1, -160).toString()).toEqual('22:20');
    });

    xtest('negative minutes rolls over continuously', () => {
      expect(new Clock(1, -4820).toString()).toEqual('16:40');
    });

    xtest('negative sixty minutes is previous hour', () => {
      expect(new Clock(2, -60).toString()).toEqual('01:00');
    });

    xtest('negative hour and minutes both roll over', () => {
      expect(new Clock(-25, -160).toString()).toEqual('20:20');
    });

    xtest('negative hour and minutes both roll over continuously', () => {
      expect(new Clock(-121, -5810).toString()).toEqual('22:10');
    });
  });

  describe('Adding minutes', () => {
    xtest('add minutes', () => {
      expect(new Clock(10, 0).plus(3).toString()).toEqual('10:03');
    });

    xtest('add no minutes', () => {
      expect(new Clock(6, 41).plus(0).toString()).toEqual('06:41');
    });

    xtest('add to next hour', () => {
      expect(new Clock(0, 45).plus(40).toString()).toEqual('01:25');
    });

    xtest('add more than one hour', () => {
      expect(new Clock(10, 0).plus(61).toString()).toEqual('11:01');
    });

    xtest('add more than two hours with carry', () => {
      expect(new Clock(0, 45).plus(160).toString()).toEqual('03:25');
    });

    xtest('add across midnight', () => {
      expect(new Clock(23, 59).plus(2).toString()).toEqual('00:01');
    });

    xtest('add more than one day (1500 min = 25 hrs)', () => {
      expect(new Clock(5, 32).plus(1500).toString()).toEqual('06:32');
    });

    xtest('add more than two days', () => {
      expect(new Clock(1, 1).plus(3500).toString()).toEqual('11:21');
    });
  });

  describe('Subtract minutes', () => {
    xtest('subtract minutes', () => {
      expect(new Clock(10, 3).minus(3).toString()).toEqual('10:00');
    });

    xtest('subtract to previous hour', () => {
      expect(new Clock(10, 3).minus(30).toString()).toEqual('09:33');
    });

    xtest('subtract more than an hour', () => {
      expect(new Clock(10, 3).minus(70).toString()).toEqual('08:53');
    });

    xtest('subtract across midnight', () => {
      expect(new Clock(0, 3).minus(4).toString()).toEqual('23:59');
    });

    xtest('subtract more than two hours', () => {
      expect(new Clock(0, 0).minus(160).toString()).toEqual('21:20');
    });

    xtest('subtract more than two hours with borrow', () => {
      expect(new Clock(6, 15).minus(160).toString()).toEqual('03:35');
    });

    xtest('subtract more than one day (1500 min = 25 hrs)', () => {
      expect(new Clock(5, 32).minus(1500).toString()).toEqual('04:32');
    });

    xtest('subtract more than two days', () => {
      expect(new Clock(2, 20).minus(3000).toString()).toEqual('00:20');
    });
  });

  describe('Compare two clocks for equality', () => {
    xtest('clocks with same time', () => {
      expect(new Clock(15, 37).equals(new Clock(15, 37))).toBe(true);
    });

    xtest('clocks a minute apart', () => {
      expect(new Clock(15, 36).equals(new Clock(15, 37))).toBe(false);
    });

    xtest('clocks an hour apart', () => {
      expect(new Clock(14, 37).equals(new Clock(15, 37))).toBe(false);
    });

    xtest('clocks with hour overflow', () => {
      expect(new Clock(10, 37).equals(new Clock(34, 37))).toBe(true);
    });

    xtest('clocks with hour overflow by several days', () => {
      expect(new Clock(3, 11).equals(new Clock(99, 11))).toBe(true);
    });

    xtest('clocks with negative hour', () => {
      expect(new Clock(22, 40).equals(new Clock(-2, 40))).toBe(true);
    });

    xtest('clocks with negative hour that wraps', () => {
      expect(new Clock(17, 3).equals(new Clock(-31, 3))).toBe(true);
    });

    xtest('clocks with negative hour that wraps multiple times', () => {
      expect(new Clock(13, 49).equals(new Clock(-83, 49))).toBe(true);
    });

    xtest('clocks with minute overflow', () => {
      expect(new Clock(0, 1).equals(new Clock(0, 1441))).toBe(true);
    });

    xtest('clocks with minute overflow by several days', () => {
      expect(new Clock(2, 2).equals(new Clock(2, 4322))).toBe(true);
    });

    xtest('clocks with negative minute', () => {
      expect(new Clock(2, 40).equals(new Clock(3, -20))).toBe(true);
    });

    xtest('clocks with negative minute that wraps', () => {
      expect(new Clock(4, 10).equals(new Clock(5, -1490))).toBe(true);
    });

    xtest('clocks with negative minute that wraps multiple times', () => {
      expect(new Clock(6, 15).equals(new Clock(6, -4305))).toBe(true);
    });

    xtest('clocks with negative hours and minutes', () => {
      expect(new Clock(7, 32).equals(new Clock(-12, -268))).toBe(true);
    });

    xtest('clocks with negative hours and minutes that wrap', () => {
      expect(new Clock(18, 7).equals(new Clock(-54, -11513))).toBe(true);
    });

    xtest('full clock and zeroed clock', () => {
      expect(new Clock(24, 0).equals(new Clock(0, 0))).toBe(true);
    });
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { ComplexNumber } from './complex-numbers';

describe('Complex numbers', () => {
  describe('Real part', () => {
    test('Real part of a purely real number', () => {
      const expected = 1;
      const actual = new ComplexNumber(1, 0).real;

      expect(actual).toEqual(expected);
    });

    xtest('Real part of a purely imaginary number', () => {
      const expected = 0;
      const actual = new ComplexNumber(0, 1).real;

      expect(actual).toEqual(expected);
    });

    xtest('Real part of a number with real and imaginary part', () => {
      const expected = 1;
      const actual = new ComplexNumber(1, 2).real;

      expect(actual).toEqual(expected);
    });
  });

  describe('Imaginary part', () => {
    xtest('Imaginary part of a purely real number', () => {
      const expected = 0;
      const actual = new ComplexNumber(1, 0).imag;

      expect(actual).toEqual(expected);
    });

    xtest('Imaginary part of a purely imaginary number', () => {
      const expected = 1;
      const actual = new ComplexNumber(0, 1).imag;

      expect(actual).toEqual(expected);
    });

    xtest('Imaginary part of a number with real and imaginary part', () => {
      const expected = 2;
      const actual = new ComplexNumber(1, 2).imag;

      expect(actual).toEqual(expected);
    });
  });

  xtest('Imaginary unit', () => {
    const expected = new ComplexNumber(-1, 0);
    const actual = new ComplexNumber(0, 1).mul(new ComplexNumber(0, 1));

    expect(actual).toEqual(expected);
  });

  describe('Arithmetic', () => {
    xtest('Add purely real numbers', () => {
      const expected = new ComplexNumber(3, 0);
      const actual = new ComplexNumber(1, 0).add(new ComplexNumber(2, 0));

      expect(actual).toEqual(expected);
    });

    xtest('Add purely imaginary numbers', () => {
      const expected = new ComplexNumber(0, 3);
      const actual = new ComplexNumber(0, 1).add(new ComplexNumber(0, 2));

      expect(actual).toEqual(expected);
    });

    xtest('Add numbers with real and imaginary part', () => {
      const expected = new ComplexNumber(4, 6);
      const actual = new ComplexNumber(1, 2).add(new ComplexNumber(3, 4));

      expect(actual).toEqual(expected);
    });

    xtest('Subtract purely real numbers', () => {
      const expected = new ComplexNumber(-1, 0);
      const actual = new ComplexNumber(1, 0).sub(new ComplexNumber(2, 0));

      expect(actual).toEqual(expected);
    });

    xtest('Subtract purely imaginary numbers', () => {
      const expected = new ComplexNumber(0, -1);
      const actual = new ComplexNumber(0, 1).sub(new ComplexNumber(0, 2));

      expect(actual).toEqual(expected);
    });

    xtest('Subtract numbers with real and imaginary part', () => {
      const expected = new ComplexNumber(-2, -2);
      const actual = new ComplexNumber(1, 2).sub(new ComplexNumber(3, 4));

      expect(actual).toEqual(expected);
    });

    xtest('Multiply purely real numbers', () => {
      const expected = new ComplexNumber(2, 0);
      const actual = new ComplexNumber(1, 0).mul(new ComplexNumber(2, 0));

      expect(actual).toEqual(expected);
    });

    xtest('Multiply purely imaginary numbers', () => {
      const expected = new ComplexNumber(-2, 0);
      const actual = new ComplexNumber(0, 1).mul(new ComplexNumber(0, 2));

      expect(actual).toEqual(expected);
    });

    xtest('Multiply numbers with real and imaginary part', () => {
      const expected = new ComplexNumber(-5, 10);
      const actual = new ComplexNumber(1, 2).mul(new ComplexNumber(3, 4));

      expect(actual).toEqual(expected);
    });

    xtest('Divide purely real numbers', () => {
      const expected = new ComplexNumber(0.5, 0);
      const actual = new ComplexNumber(1, 0).div(new ComplexNumber(2, 0));

      expect(actual).toEqual(expected);
    });

    xtest('Divide purely imaginary numbers', () => {
      const expected = new ComplexNumber(0.5, 0);
      const actual = new ComplexNumber(0, 1).div(new ComplexNumber(0, 2));

      expect(actual).toEqual(expected);
    });

    xtest('Divide numbers with real and imaginary part', () => {
      const expected = new ComplexNumber(0.44, 0.08);
      const actual = new ComplexNumber(1, 2).div(new ComplexNumber(3, 4));

      expect(actual).toEqual(expected);
    });
  });

  describe('Absolute value', () => {
    xtest('Absolute value of a positive purely real number', () => {
      const expected = 5;
      const actual = new ComplexNumber(5, 0).abs;

      expect(actual).toEqual(expected);
    });

    xtest('Absolute value of a negative purely real number', () => {
      const expected = 5;
      const actual = new ComplexNumber(-5, 0).abs;

      expect(actual).toEqual(expected);
    });

    xtest('Absolute value of a purely imaginary number with positive imaginary part', () => {
      const expected = 5;
      const actual = new ComplexNumber(0, 5).abs;

      expect(actual).toEqual(expected);
    });

    xtest('Absolute value of a purely imaginary number with negative imaginary part', () => {
      const expected = 5;
      const actual = new ComplexNumber(0, -5).abs;

      expect(actual).toEqual(expected);
    });

    xtest('Absolute value of a number with real and imaginary part', () => {
      const expected = 5;
      const actual = new ComplexNumber(3, 4).abs;

      expect(actual).toEqual(expected);
    });
  });

  describe('Complex conjugate', () => {
    xtest('Conjugate a purely real number', () => {
      const expected = new ComplexNumber(5, 0);
      const actual = new ComplexNumber(5, 0).conj;

      expect(actual).toEqual(expected);
    });

    xtest('Conjugate a purely imaginary number', () => {
      const expected = new ComplexNumber(0, -5);
      const actual = new ComplexNumber(0, 5).conj;

      expect(actual).toEqual(expected);
    });

    xtest('Conjugate a number with real and imaginary part', () => {
      const expected = new ComplexNumber(1, -1);
      const actual = new ComplexNumber(1, 1).conj;

      expect(actual).toEqual(expected);
    });
  });

  describe('Complex exponential function', () => {
    xtest("Euler's identity/formula", () => {
      const expected = new ComplexNumber(-1, 0);
      const actual = new ComplexNumber(0, Math.PI).exp;

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Exponential of 0', () => {
      const expected = new ComplexNumber(1, 0);
      const actual = new ComplexNumber(0, 0).exp;

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Exponential of a purely real number', () => {
      const expected = new ComplexNumber(Math.E, 0);
      const actual = new ComplexNumber(1, 0).exp;

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Exponential of a number with real and imaginary part', () => {
      const expected = new ComplexNumber(-2, 0);
      const actual = new ComplexNumber(Math.LN2, Math.PI).exp;

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Exponential resulting in a number with real and imaginary part', () => {
      const expected = new ComplexNumber(1, 1);
      const actual = new ComplexNumber(Math.LN2 / 2, Math.PI / 4).exp;

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });
  });

  describe('Operations between real numbers and complex numbers', () => {
    xtest('Add real number to complex number', () => {
      const expected = new ComplexNumber(6, 2);
      const actual = new ComplexNumber(1, 2).add(new ComplexNumber(5, 0));

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Add complex number to real number', () => {
      const expected = new ComplexNumber(6, 2);
      const actual = new ComplexNumber(5, 0).add(new ComplexNumber(1, 2));

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Subtract real number from complex number', () => {
      const expected = new ComplexNumber(1, 7);
      const actual = new ComplexNumber(5, 7).sub(new ComplexNumber(4, 0));

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Subtract complex number from real number', () => {
      const expected = new ComplexNumber(-1, -7);
      const actual = new ComplexNumber(4, 0).sub(new ComplexNumber(5, 7));

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Multiply complex number by real number', () => {
      const expected = new ComplexNumber(10, 25);
      const actual = new ComplexNumber(2, 5).mul(new ComplexNumber(5, 0));

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Multiply real number by complex number', () => {
      const expected = new ComplexNumber(10, 25);
      const actual = new ComplexNumber(5, 0).mul(new ComplexNumber(2, 5));

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Divide complex number by real number', () => {
      const expected = new ComplexNumber(1, 10);
      const actual = new ComplexNumber(10, 100).div(new ComplexNumber(10, 0));

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });

    xtest('Divide real number by complex number', () => {
      const expected = new ComplexNumber(2.5, -2.5);
      const actual = new ComplexNumber(5, 0).div(new ComplexNumber(1, 1));

      expect(actual.real).toBeCloseTo(expected.real);
      expect(actual.imag).toBeCloseTo(expected.imag);
    });
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { Board } from './connect';

describe('Judging a game of connect', () => {
  test('an empty board has no winner', () => {
    const board = [
      '. . . . .',
      ' . . . . .',
      '  . . . . .',
      '   . . . . .',
      '    . . . . .',
    ];
    expect(new Board(board).winner()).toEqual('');
  });

  xtest('X can win on a 1x1 board', () => {
    const board = ['X'];
    expect(new Board(board).winner()).toEqual('X');
  });

  xtest('O can win on a 1x1 board', () => {
    const board = ['O'];
    expect(new Board(board).winner()).toEqual('O');
  });

  xtest('only edges does not make a winner', () => {
    const board = ['O O O X', ' X . . X', '  X . . X', '   X O O O'];
    expect(new Board(board).winner()).toEqual('');
  });

  xtest('illegal diagonal does not make a winner', () => {
    const board = [
      'X O . .',
      ' O X X X',
      '  O X O .',
      '   . O X .',
      '    X X O O',
    ];
    expect(new Board(board).winner()).toEqual('');
  });

  xtest('nobody wins crossing adjacent angles', () => {
    const board = [
      'X . . .',
      ' . X O .',
      '  O . X O',
      '   . O . X',
      '    . . O .',
    ];
    expect(new Board(board).winner()).toEqual('');
  });

  xtest('X wins crossing from left to right', () => {
    const board = [
      '. O . .',
      ' O X X X',
      '  O X O .',
      '   X X O X',
      '    . O X .',
    ];
    expect(new Board(board).winner()).toEqual('X');
  });

  xtest('X wins with left-hand dead end fork', () => {
    const board = ['. . X .', ' X X . .', '  . X X X', '   O O O O'];
    expect(new Board(board).winner()).toEqual('X');
  });

  xtest('X wins with right-hand dead end fork', () => {
    const board = ['. . X X', ' X X . .', '  . X X .', '   O O O O'];
    expect(new Board(board).winner()).toEqual('X');
  });

  xtest('O wins crossing from top to bottom', () => {
    const board = [
      '. O . .',
      ' O X X X',
      '  O O O .',
      '   X X O X',
      '    . O X .',
    ];
    expect(new Board(board).winner()).toEqual('O');
  });

  xtest('X wins using a convoluted path', () => {
    const board = [
      '. X X . .',
      ' X . X . X',
      '  . X . X .',
      '   . X X . .',
      '    O O O O O',
    ];
    expect(new Board(board).winner()).toEqual('X');
  });

  xtest('X wins using a spiral path', () => {
    const board = [
      'O X X X X X X X X',
      ' O X O O O O O O O',
      '  O X O X X X X X O',
      '   O X O X O O O X O',
      '    O X O X X X O X O',
      '     O X O O O X O X O',
      '      O X X X X X O X O',
      '       O O O O O O O X O',
      '        X X X X X X X X O',
    ];
    expect(new Board(board).winner()).toEqual('X');
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { Crypto } from './crypto-square';

describe('Crypto', () => {
  test('empty plaintext results in an empty ciphertext', () => {
    const crypto = new Crypto('');
    expect(crypto.ciphertext).toEqual('');
  });

  test('normalization results in empty plaintext', () => {
    const crypto = new Crypto('... --- ...');
    expect(crypto.ciphertext).toEqual('');
  });

  xtest('Lowercase', () => {
    const crypto = new Crypto('A');
    expect(crypto.ciphertext).toEqual('a');
  });

  xtest('Remove spaces', () => {
    const crypto = new Crypto('  b ');
    expect(crypto.ciphertext).toEqual('b');
  });

  xtest('Remove punctuation', () => {
    const crypto = new Crypto('@1,%!');
    expect(crypto.ciphertext).toEqual('1');
  });

  xtest('9 character plaintext results in 3 chunks of 3 characters', () => {
    const crypto = new Crypto('This is fun!');
    expect(crypto.ciphertext).toEqual('tsf hiu isn');
  });

  xtest('8 character plaintext results in 3 chunks, the last one with a trailing space', () => {
    const crypto = new Crypto('Chill out.');
    expect(crypto.ciphertext).toEqual('clu hlt io ');
  });

  // This test doesn't run on our online test runner because it will time-out
  // with most implementations. It's up to you to test your solution locally.
  test.skip(
    '54 character plaintext results in 8 chunks, the last two with trailing spaces',
    () => {
      const crypto = new Crypto(
        'If man was meant to stay on the ground, god would have given us roots.',
      );
      expect(crypto.ciphertext).toEqual(
