import { beforeEach, describe, expect, test, xtest } from '@jest/globals';
import { GradeSchool } from './grade-school';

describe('Grade School', () => {
  let school;

  beforeEach(() => {
    school = new GradeSchool();
  });

  test('Roster is empty when no student is added', () => {
    expect(school.roster()).toEqual([]);
  });

  xtest('Add a student', () => {
    expect(school.add('Aimee', 2)).toEqual(true);
  });

  xtest('Student is added to the roster', () => {
    school.add('Aimee', 2);

    const expectedDb = ['Aimee'];
    expect(school.roster()).toEqual(expectedDb);
  });

  xtest('Adding multiple students in the same grade in the roster', () => {
    expect(school.add('Blair', 2)).toEqual(true);
    expect(school.add('James', 2)).toEqual(true);
    expect(school.add('Paul', 2)).toEqual(true);
  });

  xtest('Multiple students in the same grade are added to the roster', () => {
    school.add('Blair', 2);
    school.add('James', 2);
    school.add('Paul', 2);

    const expectedDb = ['Blair', 'James', 'Paul'];
    expect(school.roster()).toEqual(expectedDb);
  });

  xtest('Cannot add student to same grade in the roster more than once', () => {
    expect(school.add('Blair', 2)).toEqual(true);
    expect(school.add('James', 2)).toEqual(true);
    expect(school.add('James', 2)).toEqual(false);
    expect(school.add('Paul', 2)).toEqual(true);
  });

  xtest('Student not added to same grade in the roster more than once', () => {
    school.add('Blair', 2);
    school.add('James', 2);
    school.add('James', 2);
    school.add('Paul', 2);

    const expectedDb = ['Blair', 'James', 'Paul'];
    expect(school.roster()).toEqual(expectedDb);
  });

  xtest('Adding students in multiple grades', () => {
    expect(school.add('Chelsea', 3)).toEqual(true);
    expect(school.add('Logan', 7)).toEqual(true);
  });

  xtest('Students in multiple grades are added to the roster', () => {
    school.add('Chelsea', 3);
    school.add('Logan', 7);

    const expectedDb = ['Chelsea', 'Logan'];
    expect(school.roster()).toEqual(expectedDb);
  });

  xtest('Cannot add same student to multiple grades in the roster', () => {
    expect(school.add('Blair', 2)).toEqual(true);
    expect(school.add('James', 2)).toEqual(true);
    expect(school.add('James', 3)).toEqual(false);
    expect(school.add('Paul', 3)).toEqual(true);
  });

  xtest('Student not added to multiple grades in the roster', () => {
    school.add('Blair', 2);
    school.add('James', 2);
    school.add('James', 3);
    school.add('Paul', 3);

    const expectedDb = ['Blair', 'James', 'Paul'];
    expect(school.roster()).toEqual(expectedDb);
  });

  xtest('Students are sorted by grades in the roster', () => {
    school.add('Jim', 3);
    school.add('Peter', 2);
    school.add('Anna', 1);

    const expectedDb = ['Anna', 'Peter', 'Jim'];
    expect(school.roster()).toEqual(expectedDb);
  });

  xtest('Students are sorted by name in the roster', () => {
    school.add('Peter', 2);
    school.add('Zoe', 2);
    school.add('Alex', 2);

    const expectedDb = ['Alex', 'Peter', 'Zoe'];
    expect(school.roster()).toEqual(expectedDb);
  });

  xtest('Students are sorted by grades and then by name in the roster', () => {
    school.add('Peter', 2);
    school.add('Anna', 1);
    school.add('Barb', 1);
    school.add('Zoe', 2);
    school.add('Alex', 2);
    school.add('Jim', 3);
    school.add('Charlie', 1);

    const expectedDb = [
      'Anna',
      'Barb',
      'Charlie',
      'Alex',
      'Peter',
      'Zoe',
      'Jim',
    ];
    expect(school.roster()).toEqual(expectedDb);
  });

  xtest('Grade is empty if no students in the roster', () => {
    expect(school.grade(1)).toEqual([]);
  });

  xtest('Grade is empty if no students in that grade', () => {
    school.add('Peter', 2);
    school.add('Zoe', 2);
    school.add('Alex', 2);
    school.add('Jim', 3);

    expect(school.grade(1)).toEqual([]);
  });

  xtest('Student not added to same grade more than once', () => {
    school.add('Blair', 2);
    school.add('James', 2);
    school.add('James', 2);
    school.add('Paul', 2);

    const expectedDb = ['Blair', 'James', 'Paul'];
    expect(school.grade(2)).toEqual(expectedDb);
  });

  xtest('Student not added to multiple grades', () => {
    school.add('Blair', 2);
    school.add('James', 2);
    school.add('James', 3);
    school.add('Paul', 3);

    const expectedDb = ['Blair', 'James'];
    expect(school.grade(2)).toEqual(expectedDb);
  });

  xtest('Student not added to other grade for multiple grades', () => {
    school.add('Blair', 2);
    school.add('James', 2);
    school.add('James', 3);
    school.add('Paul', 3);

    const expectedDb = ['Paul'];
    expect(school.grade(3)).toEqual(expectedDb);
  });

  xtest('Students are sorted by name in a grade', () => {
    school.add('Franklin', 5);
    school.add('Bradley', 5);
    school.add('Jeff', 1);

    const expectedDb = ['Bradley', 'Franklin'];
    expect(school.grade(5)).toEqual(expectedDb);
  });
});

/**
 * In JavaScript, integers beyond +/- 9007199254740991 (available as the
 * Number.MIN_SAFE_INTEGER and NUMBER.MAX_SAFE_INTEGER constants) cannot be
 * accurately represented by the default "Number" type. To see this in action,
 * console.log() out the expected number of grains on square #64:
 *
 * console.log(9223372036854775808);
 * // =>       9223372036854776000
 * //                         ^^^^
 *
 * This is because, in JavaScript, "Number" type integers are actually
 * represented internally as 64-bit floating point numbers. If you want to learn
 * more, see:
 *
 * https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number/MAX_SAFE_INTEGER
 * http://stackoverflow.com/questions/307179/what-is-javascripts-highest-integer-value-that-a-number-can-go-to-without-losin
 *
 * Historically, this limitation could only be overcome by use third-party
 * implementations of a "bit integer" type like "BigInteger.js"
 * (https://github.com/peterolson/BigInteger.js).
 *
 * However, a new JavaScript arbitrary precision integer type named "BigInt",
 * which you should use to solve this exercise, is in the late stages of
 * ECMAScript standardisation and already available in most major browsers and
 * Node.js >= 10.4.0. For more details see:
 *
 * https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/BigInt
 */

import { describe, expect, test, xtest } from '@jest/globals';
import { square, total } from './grains';

describe('Grains', () => {
  describe('returns the number of grains on the square', () => {
    test('grains on square 1', () => {
      expect(square(1).toString()).toEqual('1');
    });

    xtest('grains on square 2', () => {
      expect(square(2).toString()).toEqual('2');
    });

    xtest('grains on square 3', () => {
      expect(square(3).toString()).toEqual('4');
    });

    xtest('grains on square 4', () => {
      expect(square(4).toString()).toEqual('8');
    });

    xtest('grains on square 16', () => {
      expect(square(16).toString()).toEqual('32768');
    });

    xtest('grains on square 32', () => {
      expect(square(32).toString()).toEqual('2147483648');
    });

    xtest('grains on square 64', () => {
      expect(square(64).toString()).toEqual('9223372036854775808');
    });

    xtest('square 0 raises an exception', () => {
      expect(() => square(0)).toThrow(
        new Error('square must be between 1 and 64'),
      );
    });

    xtest('negative square raises an exception', () => {
      expect(() => square(-1)).toThrow(
        new Error('square must be between 1 and 64'),
      );
    });

    xtest('square greater than 64 raises an exception', () => {
      expect(() => square(65)).toThrow(
        new Error('square must be between 1 and 64'),
      );
    });
  });

  xtest('returns the total number of grains on the board', () => {
    expect(total().toString()).toEqual('18446744073709551615');
  });
});

