    expect(garden1.plants('Charlie')).toEqual([
      'grass',
      'violets',
      'clover',
      'grass',
    ]);
    expect(garden2.plants('Charlie')).toEqual([
      'radishes',
      'radishes',
      'grass',
      'clover',
    ]);
  });
});

import { describe, expect, test } from '@jest/globals';
import { knapsack } from './knapsack';

describe('Knapsack', () => {
  test('no items', () => {
    expect(knapsack(100, [])).toEqual(0);
  });

  xtest('one item, too heavy', () => {
    const items = [{ weight: 100, value: 1 }];
    expect(knapsack(10, items)).toEqual(0);
  });

  xtest('five items (cannot be greedy by weight)', () => {
    const items = [
      { weight: 2, value: 5 },
      { weight: 2, value: 5 },
      { weight: 2, value: 5 },
      { weight: 2, value: 5 },
      { weight: 10, value: 21 },
    ];
    expect(knapsack(10, items)).toEqual(21);
  });

  xtest('five items (cannot be greedy by value)', () => {
    const items = [
      { weight: 2, value: 20 },
      { weight: 2, value: 20 },
      { weight: 2, value: 20 },
      { weight: 2, value: 20 },
      { weight: 10, value: 50 },
    ];
    expect(knapsack(10, items)).toEqual(80);
  });

  xtest('example knapsack', () => {
    const items = [
      { weight: 5, value: 10 },
      { weight: 4, value: 40 },
      { weight: 6, value: 30 },
      { weight: 4, value: 50 },
    ];
    expect(knapsack(10, items)).toEqual(90);
  });

  xtest('8 items', () => {
