import { describe, expect, test, xtest } from '@jest/globals';
import { largestProduct } from './largest-series-product';

describe('Largest Series Product', () => {
  test('finds the largest product if span equals length', () => {
    expect(largestProduct('29', 2)).toEqual(18);
  });

  xtest('can find the largest product of 2 with numbers in order', () => {
    expect(largestProduct('0123456789', 2)).toEqual(72);
  });

  xtest('can find the largest product of 2', () => {
    expect(largestProduct('576802143', 2)).toEqual(48);
  });

  xtest('can find the largest product of 3 with numbers in order', () => {
    expect(largestProduct('0123456789', 3)).toEqual(504);
  });

  xtest('can find the largest product of 3', () => {
    expect(largestProduct('1027839564', 3)).toEqual(270);
  });

  xtest('can find the largest product of 5 with numbers in order', () => {
    expect(largestProduct('0123456789', 5)).toEqual(15120);
  });

  xtest('can get the largest product of a big number', () => {
    expect(
      largestProduct('73167176531330624919225119674426574742355349194934', 6),
    ).toEqual(23520);
  });

  xtest('reports zero if the only digits are zero', () => {
    expect(largestProduct('0000', 2)).toEqual(0);
  });

  xtest('reports zero if all spans include zero', () => {
    expect(largestProduct('99099', 3)).toEqual(0);
  });

  xtest('rejects span longer than string length', () => {
    expect(() => largestProduct('123', 4)).toThrow(
      new Error('span must not exceed string length'),
    );
  });

  xtest('rejects empty string and nonzero span', () => {
    expect(() => largestProduct('', 1)).toThrow(
      new Error('span must not exceed string length'),
    );
  });

  xtest('rejects invalid character in digits', () => {
    expect(() => largestProduct('1234a5', 2)).toThrow(
      new Error('digits input must only contain digits'),
    );
  });

  xtest('rejects negative span', () => {
    expect(() => largestProduct('12345', -1)).toThrow(
      new Error('span must not be negative'),
    );
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { createEntry, formatEntries } from './ledger';

describe('Ledger', () => {
  test('empty ledger', () => {
    let currency = 'USD';
    let locale = 'en-US';
    let entries = [];
    let expected = [
      'Date       | Description               | Change       ',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });

  xtest('one entry', () => {
    let currency = 'USD';
    let locale = 'en-US';
    let entries = [createEntry('2015-01-01', 'Buy present', -1000)];
    let expected = [
      'Date       | Description               | Change       ',
      '01/01/2015 | Buy present               |      ($10.00)',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });

  xtest('credit and debit', () => {
    let currency = 'USD';
    let locale = 'en-US';
    let entries = [
      createEntry('2015-01-02', 'Get present', 1000),
      createEntry('2015-01-01', 'Buy present', -1000),
    ];
    let expected = [
      'Date       | Description               | Change       ',
      '01/01/2015 | Buy present               |      ($10.00)',
      '01/02/2015 | Get present               |       $10.00 ',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });

  xtest('final order tie breaker is change', () => {
    let currency = 'USD';
    let locale = 'en-US';
    let entries = [
      createEntry('2015-01-01', 'Something', 0),
      createEntry('2015-01-01', 'Something', -1),
      createEntry('2015-01-01', 'Something', 1),
    ];
    let expected = [
      'Date       | Description               | Change       ',
      '01/01/2015 | Something                 |       ($0.01)',
      '01/01/2015 | Something                 |        $0.00 ',
      '01/01/2015 | Something                 |        $0.01 ',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });

  xtest('overlong description is truncated', () => {
    let currency = 'USD';
    let locale = 'en-US';
    let entries = [
      createEntry('2015-01-01', 'Freude schoner Gotterfunken', -123456),
    ];
    let expected = [
      'Date       | Description               | Change       ',
      '01/01/2015 | Freude schoner Gotterf... |   ($1,234.56)',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });

  xtest('euros', () => {
    let currency = 'EUR';
    let locale = 'en-US';
    let entries = [createEntry('2015-01-01', 'Buy present', -1000)];
    let expected = [
      'Date       | Description               | Change       ',
      '01/01/2015 | Buy present               |      (€10.00)',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });

  xtest('Dutch locale', () => {
    let currency = 'USD';
    let locale = 'nl-NL';
    let entries = [createEntry('2015-03-12', 'Buy present', 123456)];
    let expected = [
      'Datum      | Omschrijving              | Verandering  ',
      '12-03-2015 | Buy present               |   $ 1.234,56 ',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });

  xtest('Dutch locale and euros', () => {
    let currency = 'EUR';
    let locale = 'nl-NL';
    let entries = [createEntry('2015-03-12', 'Buy present', 123456)];
    let expected = [
      'Datum      | Omschrijving              | Verandering  ',
      '12-03-2015 | Buy present               |   € 1.234,56 ',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });

  xtest('Dutch negative number with 3 digits before decimal point', () => {
    let currency = 'USD';
    let locale = 'nl-NL';
    let entries = [createEntry('2015-03-12', 'Buy present', -12345)];
    let expected = [
      'Datum      | Omschrijving              | Verandering  ',
      '12-03-2015 | Buy present               |    $ -123,45 ',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });

  xtest('American negative number with 3 digits before decimal point', () => {
    let currency = 'USD';
    let locale = 'en-US';
    let entries = [createEntry('2015-03-12', 'Buy present', -12345)];
    let expected = [
      'Date       | Description               | Change       ',
      '03/12/2015 | Buy present               |     ($123.45)',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });

  xtest('multiple entries on same date ordered by description', () => {
    let currency = 'USD';
    let locale = 'en-US';
    let entries = [
      createEntry('2015-01-01', 'Get present', 1000),
      createEntry('2015-01-01', 'Buy present', -1000),
    ];
    let expected = [
      'Date       | Description               | Change       ',
      '01/01/2015 | Buy present               |      ($10.00)',
      '01/01/2015 | Get present               |       $10.00 ',
    ].join('\n');
    expect(formatEntries(currency, locale, entries)).toEqual(expected);
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { Address } from './address';
import { Born } from './born';
import { Name } from './name';
import { Person } from './person';

import { bornAtLens, nameLens, streetLens } from './lens-person';

// test data
const person = new Person(
  new Name('Saravanan', 'Lakshmanan'),
  new Born(
    new Address(100, 'Hospital street', 'Tamil Nadu', 'India'),
    new Date(),
  ),
  new Address(1, 'Coder street', 'Tamil Nadu', 'India'),
);

// test suite for nameLens
describe('nameLens', () => {
  test('should get the name of the person', () => {
    expect(nameLens.get(person)).toEqual(person.name);
  });

  xtest('should set a new forename for the person', () => {
    const updatedPerson = nameLens.set(person, new Name('Sara', 'Lakshmanan'));
    expect(nameLens.get(updatedPerson)).toEqual(updatedPerson.name);
  });

  xtest('should set a new surname for the person', () => {
    const updatedPerson = nameLens.set(person, new Name('Saravanan', 'Laksh'));
    expect(nameLens.get(updatedPerson)).toEqual(updatedPerson.name);
  });

  xtest('should ensure immutability when setting a new name', () => {
    const originalName = new Name('Saravanan', 'Lakshmanan');
    nameLens.set(person, new Name('Subhash', 'Forst'));
    expect(person.name).toStrictEqual(originalName);
  });
});

// Test suite for bornAtLens
describe('bornAtLens', () => {
  xtest('should get the address for where the person was born', () => {
    expect(bornAtLens.get(person)).toEqual(person.born.bornAt);
  });

  xtest('should set a new address for where the person was born', () => {
    const updatedPerson = bornAtLens.set(
      person,
      new Address(2, 'Exercism street', 'Tamil Nadu', 'India'),
    );
    expect(bornAtLens.get(updatedPerson)).toEqual(updatedPerson.born.bornAt);
  });

  xtest('should ensure immutability when setting a new birth address', () => {
    const originalBirthAddress = new Address(
      100,
      'Hospital street',
      'Tamil Nadu',
      'India',
    );
    bornAtLens.set(person, new Address(15, 'Clinic street', 'Kerala', 'India'));
    expect(person.born.bornAt).toStrictEqual(originalBirthAddress);
  });
});

// Test suite for streetLens
describe('streetLens', () => {
  xtest('should get the current street of the person', () => {
    expect(streetLens.get(person)).toEqual(person.address.street);
  });

  xtest('should set a new street for the current address of the person', () => {
    const updatedPerson = streetLens.set(person, 'Exercism street');
    expect(streetLens.get(updatedPerson)).toEqual(updatedPerson.address.street);
  });

  xtest('should ensure immutability when setting a new street', () => {
    const originalAddress = new Address(
      1,
      'Coder street',
      'Tamil Nadu',
      'India',
    );
    streetLens.set(person, 'Mimic street');
    expect(person.address).toStrictEqual(originalAddress);
  });
});

