import { List } from './list-ops';

describe('append entries to a list and return the new list', () => {
  test('empty lists', () => {
    const list1 = new List();
    const list2 = new List();
    expect(list1.append(list2)).toEqual(new List());
  });

  xtest('list to empty list', () => {
    const list1 = new List();
    const list2 = new List([1, 2, 3, 4]);
    expect(list1.append(list2)).toEqual(list2);
  });

  xtest('empty list to list', () => {
    const list1 = new List([1, 2, 3, 4]);
    const list2 = new List();
    expect(list1.append(list2)).toEqual(list1);
  });

  xtest('non-empty lists', () => {
    const list1 = new List([1, 2]);
    const list2 = new List([2, 3, 4, 5]);
    expect(list1.append(list2).values).toEqual([1, 2, 2, 3, 4, 5]);
  });
});

describe('concat lists and lists of lists into new list', () => {
  xtest('empty list', () => {
    const list1 = new List();
    const list2 = new List();
    expect(list1.concat(list2).values).toEqual([]);
  });

  xtest('list of lists', () => {
    const list1 = new List([1, 2]);
    const list2 = new List([3]);
    const list3 = new List([]);
    const list4 = new List([4, 5, 6]);
    const listOfLists = new List([list2, list3, list4]);
    expect(list1.concat(listOfLists).values).toEqual([1, 2, 3, 4, 5, 6]);
  });

  xtest('list of nested lists', () => {
    const list1 = new List([[1], [2]]);
    const list2 = new List([[3]]);
    const list3 = new List([[]]);
    const list4 = new List([[4, 5, 6]]);
    const listOfNestedLists = new List([list2, list3, list4]);
    expect(list1.concat(listOfNestedLists).values).toEqual([
      [1],
      [2],
      [3],
      [],
      [4, 5, 6],
    ]);
  });
});

describe('filter list returning only values that satisfy the filter function', () => {
  xtest('empty list', () => {
    const list1 = new List([]);
    expect(list1.filter((el) => el % 2 === 1).values).toEqual([]);
  });

  xtest('non empty list', () => {
    const list1 = new List([1, 2, 3, 5]);
    expect(list1.filter((el) => el % 2 === 1).values).toEqual([1, 3, 5]);
  });
});

describe('returns the length of a list', () => {
  xtest('empty list', () => {
    const list1 = new List();
    expect(list1.length()).toEqual(0);
  });

  xtest('non-empty list', () => {
    const list1 = new List([1, 2, 3, 4]);
    expect(list1.length()).toEqual(4);
  });
});

describe('returns a list of elements whose values equal the list value transformed by the mapping function', () => {
  xtest('empty list', () => {
    const list1 = new List();
    expect(list1.map((el) => ++el).values).toEqual([]);
  });

  xtest('non-empty list', () => {
    const list1 = new List([1, 3, 5, 7]);
    expect(list1.map((el) => ++el).values).toEqual([2, 4, 6, 8]);
  });
});

describe('folds (reduces) the given list from the left with a function', () => {
  xtest('empty list', () => {
    const list1 = new List();
    expect(list1.foldl((acc, el) => el * acc, 2)).toEqual(2);
  });

  xtest('direction independent function applied to non-empty list', () => {
    const list1 = new List([1, 2, 3, 4]);
    expect(list1.foldl((acc, el) => acc + el, 5)).toEqual(15);
  });

  xtest('direction dependent function applied to non-empty list', () => {
    const list1 = new List([1, 2, 3, 4]);
    expect(list1.foldl((acc, el) => el / acc, 24)).toEqual(64);
  });
});

describe('folds (reduces) the given list from the right with a function', () => {
  xtest('empty list', () => {
    const list1 = new List();
    expect(list1.foldr((acc, el) => el * acc, 2)).toEqual(2);
  });

  xtest('direction independent function applied to non-empty list', () => {
    const list1 = new List([1, 2, 3, 4]);
    expect(list1.foldr((acc, el) => acc + el, 5)).toEqual(15);
  });

  xtest('direction dependent function applied to non-empty list', () => {
    const list1 = new List([1, 2, 3, 4]);
    expect(list1.foldr((acc, el) => el / acc, 24)).toEqual(9);
  });
});

describe('reverse the elements of a list', () => {
  xtest('empty list', () => {
    const list1 = new List();
    expect(list1.reverse().values).toEqual([]);
  });

  xtest('non-empty list', () => {
    const list1 = new List([1, 3, 5, 7]);
    expect(list1.reverse().values).toEqual([7, 5, 3, 1]);
  });

  xtest('list of lists is not flattened', () => {
    const list1 = new List([[1, 2], [3], [], [4, 5, 6]]);
    expect(list1.reverse().values).toEqual([[4, 5, 6], [], [3], [1, 2]]);
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { valid } from './luhn';

describe('Luhn', () => {
  test('single digit strings can not be valid', () => {
    expect(valid('1')).toEqual(false);
  });

  xtest('a single zero is invalid', () => {
    expect(valid('0')).toEqual(false);
  });

  xtest('a simple valid SIN that remains valid if reversed', () => {
    expect(valid('059')).toEqual(true);
  });

  xtest('a simple valid SIN that becomes invalid if reversed', () => {
    expect(valid('59')).toEqual(true);
  });

  xtest('a valid Canadian SIN', () => {
    expect(valid('055 444 285')).toEqual(true);
  });

  xtest('invalid Canadian SIN', () => {
    expect(valid('055 444 286')).toEqual(false);
  });

  xtest('invalid credit card', () => {
    expect(valid('8273 1232 7352 0569')).toEqual(false);
  });

  xtest('invalid long number with an even remainder', () => {
    expect(valid('1 2345 6789 1234 5678 9012')).toEqual(false);
  });

  xtest('invalid long number with a remainder divisible by 5', () => {
    expect(valid('1 2345 6789 1234 5678 9013')).toEqual(false);
  });

  xtest('valid number with an even number of digits', () => {
    expect(valid('095 245 88')).toEqual(true);
  });

  xtest('valid number with an odd number of spaces', () => {
    expect(valid('234 567 891 234')).toEqual(true);
  });

  xtest('valid strings with a non-digit added at the end invalid', () => {
    expect(valid('059a')).toEqual(false);
  });

  xtest('valid strings with punctuation included become invalid', () => {
    expect(valid('055-444-285')).toEqual(false);
  });

  xtest('valid strings with symbols included become invalid', () => {
    expect(valid('055# 444$ 285')).toEqual(false);
  });

  xtest('single zero with space is invalid', () => {
    expect(valid(' 0')).toEqual(false);
  });

  xtest('more than a single zero is valid', () => {
    expect(valid('0000 0')).toEqual(true);
  });

  xtest('input digit 9 is correctly converted to output digit 9', () => {
    expect(valid('091')).toEqual(true);
  });

  xtest('very long input is valid', () => {
    expect(valid('9999999999 9999999999 9999999999 9999999999')).toEqual(true);
  });

  xtest('valid luhn with an odd number of digits and non zero first digit', () => {
    expect(valid('109')).toEqual(true);
  });

  xtest("using ascii value for non-doubled non-digit isn't allowed", () => {
    expect(valid('055b 444 285')).toEqual(false);
  });

  xtest("using ascii value for doubled non-digit isn't allowed", () => {
    expect(valid(':9')).toEqual(false);
  });

  xtest("non-numeric, non-space char in the middle with a sum that's divisible by 10 isn't allowed", () => {
    expect(valid('59%59')).toEqual(false);
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { parse } from './markdown';

describe('Markdown', () => {
  test('parses normal text as a paragraph', () => {
    const markdown = 'This will be a paragraph';
    const expected = '<p>This will be a paragraph</p>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('parsing italics', () => {
    const markdown = '_This will be italic_';
    const expected = '<p><em>This will be italic</em></p>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('parsing bold text', () => {
    const markdown = '__This will be bold__';
    const expected = '<p><strong>This will be bold</strong></p>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('mixed normal, italics and bold text', () => {
    const markdown = 'This will _be_ __mixed__';
    const expected = '<p>This will <em>be</em> <strong>mixed</strong></p>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with h1 header level', () => {
    const markdown = '# This will be an h1';
    const expected = '<h1>This will be an h1</h1>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with h2 header level', () => {
    const markdown = '## This will be an h2';
    const expected = '<h2>This will be an h2</h2>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with h3 header level', () => {
    const markdown = '### This will be an h3';
    const expected = '<h3>This will be an h3</h3>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with h4 header level', () => {
    const markdown = '#### This will be an h4';
    const expected = '<h4>This will be an h4</h4>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with h5 header level', () => {
    const markdown = '##### This will be an h5';
    const expected = '<h5>This will be an h5</h5>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with h6 header level', () => {
    const markdown = '###### This will be an h6';
    const expected = '<h6>This will be an h6</h6>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with h7 header level', () => {
    const markdown = '####### This will not be an h7';
    const expected = '<p>####### This will not be an h7</p>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('unordered lists', () => {
    const markdown = '* Item 1\n' + '* Item 2';
    const expected = '<ul><li>Item 1</li><li>Item 2</li></ul>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with a little bit of everything', () => {
    const markdown = '# Header!\n' + '* __Bold Item__\n' + '* _Italic Item_';
    const expected =
      '<h1>Header!</h1><ul><li><strong>Bold Item</strong></li><li><em>Italic Item</em></li></ul>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with markdown symbols in the header text that should not be interpreted', () => {
    const markdown = '# This is a header with # and * in the text';
    const expected = '<h1>This is a header with # and * in the text</h1>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with markdown symbols in the list item text that should not be interpreted', () => {
    const markdown =
      '* Item 1 with a # in the text\n' + '* Item 2 with * in the text';
    const expected =
      '<ul><li>Item 1 with a # in the text</li><li>Item 2 with * in the text</li></ul>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('with markdown symbols in the paragraph text that should not be interpreted', () => {
    const markdown = 'This is a paragraph with # and * in the text';
    const expected = '<p>This is a paragraph with # and * in the text</p>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });

  xtest('unordered lists close properly with preceding and following lines', () => {
    const markdown =
      '# Start a list\n' + '* Item 1\n' + '* Item 2\n' + 'End a list';
    const expected =
      '<h1>Start a list</h1><ul><li>Item 1</li><li>Item 2</li></ul><p>End a list</p>';
    const actual = parse(markdown);
    expect(actual).toEqual(expected);
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { isPaired } from './matching-brackets';

describe('Matching Brackets', () => {
  test('paired square brackets', () => {
    expect(isPaired('[]')).toEqual(true);
  });

  xtest('empty string', () => {
    expect(isPaired('')).toEqual(true);
  });

  xtest('unpaired brackets', () => {
    expect(isPaired('[[')).toEqual(false);
  });

  xtest('wrong ordered brackets', () => {
    expect(isPaired('}{')).toEqual(false);
  });

  xtest('wrong closing bracket', () => {
    expect(isPaired('{]')).toEqual(false);
  });

  xtest('paired with whitespace', () => {
    expect(isPaired('{ }')).toEqual(true);
  });

  xtest('partially paired brackets', () => {
    expect(isPaired('{[])')).toEqual(false);
  });

  xtest('simple nested brackets', () => {
    expect(isPaired('{[]}')).toEqual(true);
  });

  xtest('several paired brackets', () => {
    expect(isPaired('{}[]')).toEqual(true);
  });

  xtest('paired and nested brackets', () => {
    expect(isPaired('([{}({}[])])')).toEqual(true);
  });

  xtest('unopened closing brackets', () => {
    expect(isPaired('{[)][]}')).toEqual(false);
  });

  xtest('unpaired and nested brackets', () => {
    expect(isPaired('([{])')).toEqual(false);
  });

  xtest('paired and wrong nested brackets', () => {
    expect(isPaired('[({]})')).toEqual(false);
  });

  xtest('paired and wrong nested brackets but innermost are correct', () => {
    expect(isPaired('[({}])')).toEqual(false);
  });

  xtest('paired and incomplete brackets', () => {
    expect(isPaired('{}[')).toEqual(false);
  });

  xtest('too many closing brackets', () => {
    expect(isPaired('[]]')).toEqual(false);
  });

  xtest('early unexpected brackets', () => {
    expect(isPaired(')()')).toEqual(false);
  });

  xtest('early mismatched brackets', () => {
    expect(isPaired('{)()')).toEqual(false);
  });

  xtest('math expression', () => {
    expect(isPaired('(((185 + 223.85) * 15) - 543)/2')).toEqual(true);
  });

  xtest('complex latex expression', () => {
    expect(
      isPaired(
        '\\left(\\begin{array}{cc} \\frac{1}{3} & x\\\\ \\mathrm{e}^{x} &... x^2 \\end{array}\\right)',
      ),
    ).toEqual(true);
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { Matrix } from './matrix';

describe('Matrix', () => {
  test('extract row from one number matrix', () => {
    expect(new Matrix('1').rows[0]).toEqual([1]);
  });

  xtest('can extract row', () => {
    expect(new Matrix('1 2\n3 4').rows[1]).toEqual([3, 4]);
  });

  xtest('extract row where numbers have different widths', () => {
    expect(new Matrix('1 2\n10 20').rows[1]).toEqual([10, 20]);
  });

  xtest('can extract row from non-square matrix with no corresponding column', () => {
    expect(new Matrix('1 2 3\n4 5 6\n7 8 9\n8 7 6').rows[3]).toEqual([8, 7, 6]);
  });

  xtest('extract column from one number matrix', () => {
    expect(new Matrix('1').columns[0]).toEqual([1]);
  });

  xtest('can extract column', () => {
    expect(new Matrix('1 2 3\n4 5 6\n7 8 9').columns[2]).toEqual([3, 6, 9]);
  });

  xtest('can extract column from non-square matrix with no corresponding row', () => {
    expect(new Matrix('1 2 3 4\n5 6 7 8\n9 8 7 6').columns[3]).toEqual([
      4, 8, 6,
    ]);
  });

  xtest('can extract column from non-square matrix with more columns than rows', () => {
    expect(new Matrix('1 2 3\n4 5 6').columns[2]).toEqual([3, 6]);
  });

  xtest('extract column where numbers have different widths', () => {
    expect(new Matrix('89 1903 3\n18 3 1\n9 4 800').columns[1]).toEqual([
      1903, 3, 4,
    ]);
  });
});

