import { describe, expect, test, xtest } from '@jest/globals';
import { rows } from './pascals-triangle';

describe('Pascals Triangle', () => {
  describe("Given a count, return a collection of that many rows of pascal's triangle", () => {
    test('zero rows', () => {
      expect(rows(0)).toEqual([]);
    });

    xtest('single row', () => {
      expect(rows(1)).toEqual([[1]]);
    });

    xtest('two rows', () => {
      expect(rows(2)).toEqual([[1], [1, 1]]);
    });

    xtest('three rows', () => {
      expect(rows(3)).toEqual([[1], [1, 1], [1, 2, 1]]);
    });

    xtest('four rows', () => {
      expect(rows(4)).toEqual([[1], [1, 1], [1, 2, 1], [1, 3, 3, 1]]);
    });

    xtest('five rows', () => {
      expect(rows(5)).toEqual([
        [1],
        [1, 1],
        [1, 2, 1],
        [1, 3, 3, 1],
        [1, 4, 6, 4, 1],
      ]);
    });

    xtest('six rows', () => {
      expect(rows(6)).toEqual([
        [1],
        [1, 1],
        [1, 2, 1],
        [1, 3, 3, 1],
        [1, 4, 6, 4, 1],
        [1, 5, 10, 10, 5, 1],
      ]);
    });

    xtest('ten rows', () => {
      expect(rows(10)).toEqual([
        [1],
        [1, 1],
        [1, 2, 1],
        [1, 3, 3, 1],
        [1, 4, 6, 4, 1],
        [1, 5, 10, 10, 5, 1],
        [1, 6, 15, 20, 15, 6, 1],
        [1, 7, 21, 35, 35, 21, 7, 1],
        [1, 8, 28, 56, 70, 56, 28, 8, 1],
        [1, 9, 36, 84, 126, 126, 84, 36, 9, 1],
      ]);
    });
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { classify } from './perfect-numbers';

describe('Exercise - Perfect Numbers', () => {
  describe('Invalid Inputs', () => {
    test('Zero is rejected (not a natural number)', () => {
      expect(() => classify(0)).toThrow(
        new Error('Classification is only possible for natural numbers.'),
      );
    });

    xtest('Negative integer is rejected (not a natural number)', () => {
      expect(() => classify(-1)).toThrow(
        new Error('Classification is only possible for natural numbers.'),
      );
    });
  });

  describe('Perfect Numbers', () => {
    xtest('Smallest perfect number is classified correctly', () => {
      expect(classify(6)).toEqual('perfect');
    });

    xtest('Medium perfect number is classified correctly', () => {
      expect(classify(28)).toEqual('perfect');
    });

    xtest('Large perfect number is classified correctly', () => {
      expect(classify(33550336)).toEqual('perfect');
    });
  });

  describe('Abundant Numbers', () => {
    xtest('Smallest abundant number is classified correctly', () => {
      expect(classify(12)).toEqual('abundant');
    });

    xtest('Medium abundant number is classified correctly', () => {
      expect(classify(30)).toEqual('abundant');
    });

    xtest('Large abundant number is classified correctly', () => {
      expect(classify(33550335)).toEqual('abundant');
    });

    xtest('Perfect square abundant number is classified correctly', () => {
      expect(classify(196)).toEqual('abundant');
    });
  });

  describe('Deficient Numbers', () => {
    xtest('Edge case (no factors other than itself) is classified correctly', () => {
      expect(classify(1)).toEqual('deficient');
    });

    xtest('Smallest prime deficient number is classified correctly', () => {
      expect(classify(2)).toEqual('deficient');
    });

    xtest('Smallest non-prime deficient number is classified correctly', () => {
      expect(classify(4)).toEqual('deficient');
    });

    xtest('Medium deficient number is classified correctly', () => {
      expect(classify(32)).toEqual('deficient');
    });

    xtest('Large deficient number is classified correctly', () => {
      expect(classify(33550337)).toEqual('deficient');
    });
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { clean } from './phone-number';

describe('Phone Number', () => {
  describe('Cleanup user-entered phone numbers', () => {
    test('cleans the number', () => {
      expect(clean('(223) 456-7890')).toEqual('2234567890');
    });

    xtest('cleans numbers with dots', () => {
      expect(clean('223.456.7890')).toEqual('2234567890');
    });

    xtest('cleans numbers with multiple spaces', () => {
      expect(clean('223 456   7890   ')).toEqual('2234567890');
    });

    xtest('invalid when 9 digits', () => {
      expect(() => clean('123456789')).toThrow(
        new Error('Must not be fewer than 10 digits'),
      );
    });

    xtest('invalid when 11 digits does not start with a 1', () => {
      expect(() => clean('22234567890')).toThrow(
        new Error('11 digits must start with 1'),
      );
    });

    xtest('valid when 11 digits and starting with 1', () => {
      expect(clean('12234567890')).toEqual('2234567890');
    });

    xtest('valid when 11 digits and starting with 1 even with punctuation', () => {
      expect(clean('+1 (223) 456-7890')).toEqual('2234567890');
    });

    xtest('invalid when more than 11 digits', () => {
      expect(() => clean('321234567890')).toThrow(
        new Error('Must not be greater than 11 digits'),
      );
    });

    xtest('invalid with letters', () => {
      expect(() => clean('523-abc-7890')).toThrow(
        new Error('Letters not permitted'),
      );
    });

    xtest('invalid with punctuations', () => {
      expect(() => clean('523-@:!-7890')).toThrow(
        new Error('Punctuations not permitted'),
      );
    });

    xtest('invalid if area code starts with 0', () => {
      expect(() => clean('(023) 456-7890')).toThrow(
        new Error('Area code cannot start with zero'),
      );
    });

    xtest('invalid if area code starts with 1', () => {
      expect(() => clean('(123) 456-7890')).toThrow(
        new Error('Area code cannot start with one'),
      );
    });

    xtest('invalid if exchange code starts with 0', () => {
      expect(() => clean('(223) 056-7890')).toThrow(
        new Error('Exchange code cannot start with zero'),
      );
    });

    xtest('invalid if exchange code starts with 1', () => {
      expect(() => clean('(223) 156-7890')).toThrow(
        new Error('Exchange code cannot start with one'),
      );
    });

    xtest('invalid if area code starts with 0 on valid 11-digit number', () => {
      expect(() => clean('1 (023) 456-7890')).toThrow(
        new Error('Area code cannot start with zero'),
      );
    });

    xtest('invalid if area code starts with 1 on valid 11-digit number', () => {
      expect(() => clean('1 (123) 456-7890')).toThrow(
        new Error('Area code cannot start with one'),
      );
    });

    xtest('invalid if exchange code starts with 0 on valid 11-digit number', () => {
      expect(() => clean('1 (223) 056-7890')).toThrow(
        new Error('Exchange code cannot start with zero'),
      );
    });

    xtest('invalid if exchange code starts with 1 on valid 11-digit number', () => {
      expect(() => clean('1 (223) 156-7890')).toThrow(
        new Error('Exchange code cannot start with one'),
      );
    });
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { DNA } from './point-mutations';

describe('DNA', () => {
  test('no difference between empty strands', () => {
    const dna = new DNA('');
    expect(dna.hammingDistance('')).toEqual(0);
  });

  xtest('no difference between identical strands', () => {
    const dna = new DNA('GGACTGA');
    expect(dna.hammingDistance('GGACTGA')).toEqual(0);
  });

  xtest('complete hamming distance in small strand', () => {
    const dna = new DNA('ACT');
    expect(dna.hammingDistance('GGA')).toEqual(3);
  });

  xtest('hamming distance in off by one strand', () => {
    const dna = new DNA('GGACGGATTCTGACCTGGACTAATTTTGGGG');
    expect(dna.hammingDistance('AGGACGGATTCTGACCTGGACTAATTTTGGGG')).toEqual(19);
  });

  xtest('small hamming distance in middle somewhere', () => {
    const dna = new DNA('GGACG');
    expect(dna.hammingDistance('GGTCG')).toEqual(1);
  });

  xtest('larger distance', () => {
    const dna = new DNA('ACCAGGG');
    expect(dna.hammingDistance('ACTATGG')).toEqual(2);
  });

  xtest('shortens other strand when longer', () => {
    const dna = new DNA('AAACTAGGGG');
    expect(dna.hammingDistance('AGGCTAGCGGTAGGAC')).toEqual(3);
  });

  xtest('shortens original strand when longer', () => {
    const dna = new DNA('GACTACGGACAGGGTAGGGAAT');
    expect(dna.hammingDistance('GACATCGCACACC')).toEqual(5);
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { bestHands } from './poker';

describe('Poker', () => {
  test('single hand always wins', () => {
    const hands = ['4S 5S 7H 8D JC'];
    const expected = ['4S 5S 7H 8D JC'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('highest card out of all hands wins', () => {
    const hands = ['4D 5S 6S 8D 3C', '2S 4C 7S 9H 10H', '3S 4S 5D 6H JH'];
    const expected = ['3S 4S 5D 6H JH'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('a tie has multiple winners', () => {
    const hands = [
      '4D 5S 6S 8D 3C',
      '2S 4C 7S 9H 10H',
      '3S 4S 5D 6H JH',
      '3H 4H 5C 6C JD',
    ];
    const expected = ['3S 4S 5D 6H JH', '3H 4H 5C 6C JD'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('multiple hands with the same high cards, tie compares next highest ranked, down to last card', () => {
    const hands = ['3S 5H 6S 8D 7H', '2S 5D 6D 8C 7S'];
    const expected = ['3S 5H 6S 8D 7H'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('winning high card hand also has the lowest card', () => {
    const hands = ['2S 5H 6S 8D 7H', '3S 4D 6D 8C 7S'];
    const expected = ['2S 5H 6S 8D 7H'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('one pair beats high card', () => {
    const hands = ['4S 5H 6C 8D KH', '2S 4H 6S 4D JH'];
    const expected = ['2S 4H 6S 4D JH'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('highest pair wins', () => {
    const hands = ['4S 2H 6S 2D JH', '2S 4H 6C 4D JD'];
    const expected = ['2S 4H 6C 4D JD'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands have the same pair, high card wins', () => {
    const hands = ['4H 4S AH JC 3D', '4C 4D AS 5D 6C'];
    const expected = ['4H 4S AH JC 3D'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('two pairs beats one pair', () => {
    const hands = ['2S 8H 6S 8D JH', '4S 5H 4C 8C 5C'];
    const expected = ['4S 5H 4C 8C 5C'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands have two pairs, highest ranked pair wins', () => {
    const hands = ['2S 8H 2D 8D 3H', '4S 5H 4C 8S 5D'];
    const expected = ['2S 8H 2D 8D 3H'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands have two pairs, with the same highest ranked pair, tie goes to low pair', () => {
    const hands = ['2S QS 2C QD JH', 'JD QH JS 8D QC'];
    const expected = ['JD QH JS 8D QC'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands have two identically ranked pairs, tie goes to remaining card (kicker)', () => {
    const hands = ['JD QH JS 8D QC', 'JS QS JC 2D QD'];
    const expected = ['JD QH JS 8D QC'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands have two pairs that add to the same value, win goes to highest pair', () => {
    const hands = ['6S 6H 3S 3H AS', '7H 7S 2H 2S AC'];
    const expected = ['7H 7S 2H 2S AC'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('two pairs first ranked by largest pair', () => {
    const hands = ['5C 2S 5S 4H 4C', '6S 2S 6H 7C 2C'];
    const expected = ['6S 2S 6H 7C 2C'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('three of a kind beats two pair', () => {
    const hands = ['2S 8H 2H 8D JH', '4S 5H 4C 8S 4H'];
    const expected = ['4S 5H 4C 8S 4H'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands have three of a kind, tie goes to highest ranked triplet', () => {
    const hands = ['2S 2H 2C 8D JH', '4S AH AS 8C AD'];
    const expected = ['4S AH AS 8C AD'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('with multiple decks, two players can have same three of a kind, ties go to highest remaining cards', () => {
    const hands = ['5S AH AS 7C AD', '4S AH AS 8C AD'];
    const expected = ['4S AH AS 8C AD'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('a straight beats three of a kind', () => {
    const hands = ['4S 5H 4C 8D 4H', '3S 4D 2S 6D 5C'];
    const expected = ['3S 4D 2S 6D 5C'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('aces can end a straight (10 J Q K A)', () => {
    const hands = ['4S 5H 4C 8D 4H', '10D JH QS KD AC'];
    const expected = ['10D JH QS KD AC'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('aces can start a straight (A 2 3 4 5)', () => {
    const hands = ['4S 5H 4C 8D 4H', '4D AH 3S 2D 5C'];
    const expected = ['4D AH 3S 2D 5C'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('aces cannot be in the middle of a straight (Q K A 2 3)', () => {
    const hands = ['2C 3D 7H 5H 2S', 'QS KH AC 2D 3S'];
    const expected = ['2C 3D 7H 5H 2S'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands with a straight, tie goes to highest ranked card', () => {
    const hands = ['4S 6C 7S 8D 5H', '5S 7H 8S 9D 6H'];
    const expected = ['5S 7H 8S 9D 6H'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('even though an ace is usually high, a 5-high straight is the lowest-scoring straight', () => {
    const hands = ['2H 3C 4D 5D 6H', '4S AH 3S 2D 5H'];
    const expected = ['2H 3C 4D 5D 6H'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('flush beats a straight', () => {
    const hands = ['4C 6H 7D 8D 5H', '2S 4S 5S 6S 7S'];
    const expected = ['2S 4S 5S 6S 7S'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands have a flush, tie goes to high card, down to the last one if necessary', () => {
    const hands = ['2H 7H 8H 9H 6H', '3S 5S 6S 7S 8S'];
    const expected = ['2H 7H 8H 9H 6H'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('full house beats a flush', () => {
    const hands = ['3H 6H 7H 8H 5H', '4S 5H 4C 5D 4H'];
    const expected = ['4S 5H 4C 5D 4H'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands have a full house, tie goes to highest-ranked triplet', () => {
    const hands = ['4H 4S 4D 9S 9D', '5H 5S 5D 8S 8D'];
    const expected = ['5H 5S 5D 8S 8D'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('with multiple decks, both hands have a full house with the same triplet, tie goes to the pair', () => {
    const hands = ['5H 5S 5D 9S 9D', '5H 5S 5D 8S 8D'];
    const expected = ['5H 5S 5D 9S 9D'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('four of a kind beats a full house', () => {
    const hands = ['4S 5H 4D 5D 4H', '3S 3H 2S 3D 3C'];
    const expected = ['3S 3H 2S 3D 3C'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands have four of a kind, tie goes to high quad', () => {
    const hands = ['2S 2H 2C 8D 2D', '4S 5H 5S 5D 5C'];
    const expected = ['4S 5H 5S 5D 5C'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('with multiple decks, both hands with identical four of a kind, tie determined by kicker', () => {
    const hands = ['3S 3H 2S 3D 3C', '3S 3H 4S 3D 3C'];
    const expected = ['3S 3H 4S 3D 3C'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('straight flush beats four of a kind', () => {
    const hands = ['4S 5H 5S 5D 5C', '7S 8S 9S 6S 10S'];
    const expected = ['7S 8S 9S 6S 10S'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('aces can end a straight flush (10 J Q K A)', () => {
    const hands = ['KC AH AS AD AC', '10C JC QC KC AC'];
    const expected = ['10C JC QC KC AC'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('aces can start a straight flush (A 2 3 4 5)', () => {
    const hands = ['KS AH AS AD AC', '4H AH 3H 2H 5H'];
    const expected = ['4H AH 3H 2H 5H'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('aces cannot be in the middle of a straight flush (Q K A 2 3)', () => {
    const hands = ['2C AC QC 10C KC', 'QH KH AH 2H 3H'];
    const expected = ['2C AC QC 10C KC'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('both hands have straight flush, tie goes to highest-ranked card', () => {
    const hands = ['4H 6H 7H 8H 5H', '5S 7S 8S 9S 6S'];
    const expected = ['5S 7S 8S 9S 6S'];
    expect(bestHands(hands)).toEqual(expected);
  });

  xtest('even though an ace is usually high, a 5-high straight flush is the lowest-scoring straight flush', () => {
    const hands = ['2H 3H 4H 5H 6H', '4D AD 3D 2D 5D'];
    const expected = ['2H 3H 4H 5H 6H'];
    expect(bestHands(hands)).toEqual(expected);
  });
});

