import { describe, expect, test, xtest } from '@jest/globals';
import { all, allSettled, any, promisify, race } from './promises';

describe('promises', () => {
  const failedCallback = new Error('Failed callback');

  const createCallbackFn = (speed) => (value, callback) =>
    setTimeout(() => callback(null, value), speed);
  const createFailedCallback = (speed) => (_, callback) =>
    setTimeout(() => callback(failedCallback), speed);

  const slowestCallbackFn = createCallbackFn(20);
  const slowerCallbackFn = createCallbackFn(10);
  const fastCallbackFn = createCallbackFn(0);
  const failedCallbackFn = createFailedCallback(10);

  describe('promisify', () => {
    test('returns a function', () => {
      expect(typeof promisify(fastCallbackFn)).toBe('function');
    });

    xtest('promisified function call returns a Promise', () => {
      const fastPromise = promisify(fastCallbackFn);
      expect(fastPromise('fast')).toBeInstanceOf(Promise);
    });

    xtest("promisified function resolves to a callback's success value", () => {
      const SUCCESS = 'success';
      const fastPromise = promisify(fastCallbackFn);
      return expect(fastPromise(SUCCESS)).resolves.toEqual(SUCCESS);
    });

    xtest("promisified function rejects a callback's error", () => {
      const failedPromise = promisify(failedCallbackFn);
      return expect(failedPromise(null)).rejects.toEqual(failedCallback);
    });
  });

  describe('all', () => {
    const [slowestPromise, slowerPromise, fastPromise, failedPromise] = [
      slowestCallbackFn,
      slowerCallbackFn,
      fastCallbackFn,
      failedCallbackFn,
    ].map((fn) => promisify(fn));

    xtest('returns a Promise', () => {
      expect(all([])).toBeInstanceOf(Promise);
    });

    xtest('resolves when given no promises', () => {
      return expect(all([])).resolves.toEqual([]);
    });

    xtest('resolves when given no arguments', () => {
      return expect(all()).resolves.toBeUndefined();
    });

    xtest('resolved values appear in the order they are passed in', () => {
      const FIRST = 'FIRST';
      const SECOND = 'SECOND';
      const THIRD = 'THIRD';
      const result = all([
        slowestPromise(FIRST),
        slowerPromise(SECOND),
        fastPromise(THIRD),
      ]);
      return expect(result).resolves.toEqual([FIRST, SECOND, THIRD]);
    });

    xtest('rejects if any promises fail', () => {
      const result = all([fastPromise('fast'), failedPromise(null)]);
      return expect(result).rejects.toEqual(failedCallback);
    });
  });

  describe('allSettled', () => {
    const [slowestPromise, slowerPromise, fastPromise, failedPromise] = [
      slowestCallbackFn,
      slowerCallbackFn,
      fastCallbackFn,
      failedCallbackFn,
    ].map((fn) => promisify(fn));

    xtest('returns a Promise', () => {
      expect(allSettled([])).toBeInstanceOf(Promise);
    });

    xtest('resolves when given no promises', () => {
      return expect(allSettled([])).resolves.toEqual([]);
    });

    xtest('resolves when given no arguments', () => {
      return expect(allSettled()).resolves.toBeUndefined();
    });

    xtest('resolved values appear in the order they are passed in', () => {
      const FIRST = 'FIRST';
      const SECOND = 'SECOND';
      const THIRD = 'THIRD';
      const result = allSettled([
        slowestPromise(FIRST),
        slowerPromise(SECOND),
        fastPromise(THIRD),
      ]);
      return expect(result).resolves.toEqual([FIRST, SECOND, THIRD]);
    });

    xtest('resolves even if some promises fail', () => {
      const FIRST = 'FIRST';
      const result = allSettled([fastPromise(FIRST), failedPromise(null)]);
      return expect(result).resolves.toEqual([FIRST, failedCallback]);
    });
  });

  describe('race', () => {
    const [slowestPromise, slowerPromise, fastPromise, failedPromise] = [
      slowestCallbackFn,
      slowerCallbackFn,
      fastCallbackFn,
      failedCallbackFn,
    ].map((fn) => promisify(fn));

    xtest('returns a Promise', () => {
      expect(race([])).toBeInstanceOf(Promise);
    });

    xtest('resolves when given no promises', () => {
      return expect(race([])).resolves.toEqual([]);
    });

    xtest('resolves when given no arguments', () => {
      return expect(race()).resolves.toBeUndefined();
    });

    xtest('resolves with value of the fastest successful promise', () => {
      const FAST = 'FAST';
      return expect(
        race([
          slowestPromise('SLOWEST'),
          slowerPromise('SLOWER'),
          fastPromise(FAST),
        ]),
      ).resolves.toEqual(FAST);
    });

    xtest('resolves with value of the fastest promise even if other slower promises fail', () => {
      const FAST = 'FAST';
      return expect(
        race([failedPromise(null), fastPromise(FAST)]),
      ).resolves.toEqual(FAST);
    });

    xtest('rejects if the fastest promise fails even if other slower promises succeed', () => {
      return expect(
        race([slowestPromise('SLOWEST'), failedPromise(null)]),
      ).rejects.toEqual(failedCallback);
    });
  });

  describe('any', () => {
    const [slowestPromise, slowerPromise, fastPromise, failedPromise] = [
      slowestCallbackFn,
      slowerCallbackFn,
      fastCallbackFn,
      failedCallbackFn,
    ].map((fn) => promisify(fn));

    xtest('returns a Promise', () => {
      expect(any([]).catch(() => null)).toBeInstanceOf(Promise);
    });

    xtest('resolves when given no promises', () => {
      return expect(race([])).resolves.toEqual([]);
    });

    xtest('resolves when given no arguments', () => {
      return expect(race()).resolves.toBeUndefined();
    });

    xtest('resolves with value of fastest successful promise', () => {
      const FAST = 'FAST';
      return expect(
        any([
          slowestPromise('SLOWEST'),
          slowerPromise('SLOWER'),
          fastPromise(FAST),
        ]),
      ).resolves.toEqual(FAST);
    });

    xtest('resolves with value of the fastest successful promise even if slower promises fail', () => {
      const FAST = 'FAST';
      return expect(
        any([failedPromise(null), fastPromise(FAST)]),
      ).resolves.toEqual(FAST);
    });

    xtest('resolves with value of fastest successful promise even if faster promises fail', () => {
      const SLOWEST = 'SLOWEST';
      return expect(
        any([failedPromise(null), slowestPromise(SLOWEST)]),
      ).resolves.toEqual(SLOWEST);
    });

    xtest('rejects with array of errors if all promises fail', () => {
      return expect(
        any([failedPromise(null), failedPromise(null)]),
      ).rejects.toEqual([failedCallback, failedCallback]);
    });
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { translate } from './protein-translation';

describe('ProteinTranslation', () => {
  test('Empty RNA sequence results in no proteins', () => {
    expect(translate()).toEqual([]);
  });

  describe('Single codons', () => {
    xtest('Methionine RNA sequence', () => {
      expect(translate('AUG')).toEqual(['Methionine']);
    });

    xtest('Phenylalanine RNA sequence 1', () => {
      expect(translate('UUU')).toEqual(['Phenylalanine']);
    });
    xtest('Phenylalanine RNA sequence 2', () => {
      expect(translate('UUC')).toEqual(['Phenylalanine']);
    });

    xtest('Leucine RNA sequence 1', () => {
      expect(translate('UUA')).toEqual(['Leucine']);
    });
    xtest('Leucine RNA sequence 2', () => {
      expect(translate('UUG')).toEqual(['Leucine']);
    });

    xtest('Serine RNA sequence 1', () => {
      expect(translate('UCU')).toEqual(['Serine']);
    });
    xtest('Serine RNA sequence 2', () => {
      expect(translate('UCC')).toEqual(['Serine']);
    });
    xtest('Serine RNA sequence 3', () => {
      expect(translate('UCA')).toEqual(['Serine']);
    });
    xtest('Serine RNA sequence 4', () => {
      expect(translate('UCG')).toEqual(['Serine']);
    });

    xtest('Tyrosine RNA sequence 1', () => {
      expect(translate('UAU')).toEqual(['Tyrosine']);
    });
    xtest('Tyrosine RNA sequence 2', () => {
      expect(translate('UAC')).toEqual(['Tyrosine']);
    });

    xtest('Cysteine RNA sequence 1', () => {
      expect(translate('UGU')).toEqual(['Cysteine']);
    });
    xtest('Cysteine RNA sequence 2', () => {
      expect(translate('UGC')).toEqual(['Cysteine']);
    });

    xtest('Tryptophan RNA sequence', () => {
      expect(translate('UGG')).toEqual(['Tryptophan']);
    });

    xtest('STOP codon RNA sequence 1', () => {
      expect(translate('UAA')).toEqual([]);
    });
    xtest('STOP codon RNA sequence 2', () => {
      expect(translate('UAG')).toEqual([]);
    });
    xtest('STOP codon RNA sequence 3', () => {
      expect(translate('UGA')).toEqual([]);
    });
  });

  describe('Multiple codons', () => {
    xtest('Sequence of two protein codons translates into proteins', () => {
      expect(translate('UUUUUU')).toEqual(['Phenylalanine', 'Phenylalanine']);
    });

    xtest('Sequence of two different protein codons translates into proteins', () => {
      expect(translate('UUAUUG')).toEqual(['Leucine', 'Leucine']);
    });

    xtest('Translate RNA strand into correct protein list', () => {
      expect(translate('AUGUUUUGG')).toEqual([
        'Methionine',
        'Phenylalanine',
        'Tryptophan',
      ]);
    });

    xtest('Translation stops if STOP codon at beginning of sequence', () => {
      expect(translate('UAGUGG')).toEqual([]);
    });

    xtest('Translation stops if STOP codon at end of three-codon sequence', () => {
      expect(translate('AUGUUUUAA')).toEqual(['Methionine', 'Phenylalanine']);
    });

    xtest('Translation stops if STOP codon in middle of three-codon sequence', () => {
      expect(translate('UGGUAGUGG')).toEqual(['Tryptophan']);
    });

    xtest('Translation stops if STOP codon in middle of six-codon sequence', () => {
      expect(translate('UGGUGUUAUUAAUGGUUU')).toEqual([
        'Tryptophan',
        'Cysteine',
        'Tyrosine',
      ]);
    });

    xtest('Sequence of two non-STOP codons does not translate to a STOP codon', () => {
      expect(translate('AUGAUG')).toEqual(['Methionine', 'Methionine']);
    });
  });

  describe('Unexpected strands', () => {
    xtest("Unknown amino acids, not part of a codon, can't translate", () => {
      expect(() => translate('XYZ')).toThrow(new Error('Invalid codon'));
    });

    xtest("Incomplete RNA sequence can't translate", () => {
      expect(() => translate('AUGU')).toThrow(new Error('Invalid codon'));
    });

    xtest('Incomplete RNA sequence can translate if valid until a STOP codon', () => {
      expect(translate('UUCUUCUAAUGGU')).toEqual([
        'Phenylalanine',
        'Phenylalanine',
      ]);
    });
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { proverb } from './proverb';

describe('Proverb', () => {
  test('zero pieces', () => {
    const result = proverb();

    expect(result).toEqual('');
  });

  xtest('one piece', () => {
    const result = proverb('nail');

    expect(result).toEqual('And all for the want of a nail.');
  });

  xtest('two pieces', () => {
    const result = proverb('nail', 'shoe');

    expect(result).toEqual(
      `For want of a nail the shoe was lost.
And all for the want of a nail.`,
    );
  });

  xtest('three pieces', () => {
    const result = proverb('nail', 'shoe', 'horse');

    expect(result).toEqual(
      `For want of a nail the shoe was lost.
For want of a shoe the horse was lost.
And all for the want of a nail.`,
    );
  });

  xtest('the whole proverb', () => {
    const result = proverb(
      'nail',
      'shoe',
      'horse',
      'rider',
      'message',
      'battle',
      'kingdom',
    );

    expect(result).toEqual(
      `For want of a nail the shoe was lost.
For want of a shoe the horse was lost.
For want of a horse the rider was lost.
For want of a rider the message was lost.
For want of a message the battle was lost.
For want of a battle the kingdom was lost.
And all for the want of a nail.`,
    );
  });

  xtest('proverb is the same each time', () => {
    expect(proverb('nail', 'shoe')).toEqual(proverb('nail', 'shoe'));
  });

  xtest('four pieces modernized', () => {
    const result = proverb('pin', 'gun', 'soldier', 'battle');

    expect(result).toEqual(
      `For want of a pin the gun was lost.
For want of a gun the soldier was lost.
For want of a soldier the battle was lost.
And all for the want of a pin.`,
    );
  });

  xtest('the use of an optional qualifier in the final consequence', () => {
    const result = proverb(
      'nail',
      'shoe',
      'horse',
      'rider',
      'message',
      'battle',
      'kingdom',
      { qualifier: 'horseshoe' },
    );

    expect(result).toEqual(
      `For want of a nail the shoe was lost.
For want of a shoe the horse was lost.
For want of a horse the rider was lost.
For want of a rider the message was lost.
For want of a message the battle was lost.
For want of a battle the kingdom was lost.
And all for the want of a horseshoe nail.`,
    );
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { triplets } from './pythagorean-triplet';

function tripletsWithSum(sum, options = {}) {
  return triplets({ ...options, sum }).map((triplet) =>
    triplet.toArray().sort((a, b) => a - b),
  );
}

describe('Triplet', () => {
  test('triplets whose sum is 12', () => {
    expect(tripletsWithSum(12)).toEqual([[3, 4, 5]]);
  });

  xtest('triplets whose sum is 108', () => {
    expect(tripletsWithSum(108)).toEqual([[27, 36, 45]]);
  });

  xtest('triplets whose sum is 1000', () => {
    expect(tripletsWithSum(1000)).toEqual([[200, 375, 425]]);
  });

  xtest('no matching triplets for 1001', () => {
    expect(tripletsWithSum(1001)).toEqual([]);
  });

  xtest('returns all matching triplets', () => {
    expect(tripletsWithSum(90)).toEqual([
      [9, 40, 41],
      [15, 36, 39],
    ]);
  });

  xtest('several matching triplets', () => {
    expect(tripletsWithSum(840)).toEqual([
      [40, 399, 401],
      [56, 390, 394],
      [105, 360, 375],
      [120, 350, 370],
      [140, 336, 364],
      [168, 315, 357],
      [210, 280, 350],
      [240, 252, 348],
    ]);
  });

  xtest('returns triplets with no factor smaller than minimum factor', () => {
    expect(tripletsWithSum(90, { minFactor: 10 })).toEqual([[15, 36, 39]]);
  });

  xtest('returns triplets with no factor larger than maximum factor', () => {
    expect(tripletsWithSum(840, { maxFactor: 349 })).toEqual([[240, 252, 348]]);
  });

  xtest('returns triplets with factors in range', () => {
    expect(tripletsWithSum(840, { maxFactor: 352, minFactor: 150 })).toEqual([
      [210, 280, 350],
      [240, 252, 348],
    ]);
  });

  // This test doesn't run on our online test runner because it will time-out
  // with most implementations. It's up to you to test your solution locally.
  test.skip(
    'triplets for large number',
    () => {
      expect(tripletsWithSum(30000)).toEqual([
        [1200, 14375, 14425],
        [1875, 14000, 14125],
        [5000, 12000, 13000],
        [6000, 11250, 12750],
        [7500, 10000, 12500],
      ]);
    },
    20 * 1000,
  );
});

