import { describe, expect, test, xtest } from '@jest/globals';
import { saddlePoints } from './saddle-points';

describe('Saddle Points', () => {
  test('Can identify single saddle point', () => {
    const expected = [{ row: 2, column: 1 }];
    expect(
      saddlePoints([
        [9, 8, 7],
        [5, 3, 2],
        [6, 6, 7],
      ]),
    ).toEqual(expected);
  });

  xtest('Can identify that empty matrix has no saddle points', () => {
    expect(saddlePoints([[]])).toEqual([]);
  });

  xtest('Can identify lack of saddle points when there are none', () => {
    expect(
      saddlePoints([
        [1, 2, 3],
        [3, 1, 2],
        [2, 3, 1],
      ]),
    ).toEqual([]);
  });

  xtest('Can identify multiple saddle points in a column', () => {
    const expected = [
      { row: 1, column: 2 },
      { row: 2, column: 2 },
      { row: 3, column: 2 },
    ];
    expect(
      saddlePoints([
        [4, 5, 4],
        [3, 5, 5],
        [1, 5, 4],
      ]),
    ).toEqual(expected);
  });

  xtest('Can identify multiple saddle points in a row', () => {
    const expected = [
      { row: 2, column: 1 },
      { row: 2, column: 2 },
      { row: 2, column: 3 },
    ];
    expect(
      saddlePoints([
        [6, 7, 8],
        [5, 5, 5],
        [7, 5, 6],
      ]),
    ).toEqual(expected);
  });

  xtest('Can identify saddle point in bottom right corner', () => {
    const expected = [{ row: 3, column: 3 }];
    expect(
      saddlePoints([
        [8, 7, 9],
        [6, 7, 6],
        [3, 2, 5],
      ]),
    ).toEqual(expected);
  });

  xtest('Can identify saddle points in a non square matrix', () => {
    const expected = [
      { row: 1, column: 1 },
      { row: 1, column: 3 },
    ];
    expect(
      saddlePoints([
        [3, 1, 3],
        [3, 2, 4],
      ]),
    ).toEqual(expected);
  });

  xtest('Can identify that saddle points in a single column matrix are those with the minimum value', () => {
    const expected = [
      { row: 2, column: 1 },
      { row: 4, column: 1 },
    ];
    expect(saddlePoints([[2], [1], [4], [1]])).toEqual(expected);
  });

  xtest('Can identify that saddle points in a single row matrix are those with the maximum value', () => {
    const expected = [
      { row: 1, column: 2 },
      { row: 1, column: 4 },
    ];
    expect(saddlePoints([[2, 5, 3, 5]])).toEqual(expected);
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { treeFromTraversals } from './satellite';

describe('Satellite', () => {
  test('Empty tree', () => {
    expect(treeFromTraversals([], [])).toEqual({});
  });

  xtest('Tree with one item', () => {
    const expected = { value: 'a', left: {}, right: {} };
    expect(treeFromTraversals(['a'], ['a'])).toEqual(expected);
  });

  xtest('Tree with many items', () => {
    const preorder = ['a', 'i', 'x', 'f', 'r'];
    const inorder = ['i', 'a', 'f', 'x', 'r'];
    const expected = {
      value: 'a',
      left: { value: 'i', left: {}, right: {} },
      right: {
        value: 'x',
        left: { value: 'f', left: {}, right: {} },
        right: { value: 'r', left: {}, right: {} },
      },
    };
    expect(treeFromTraversals(preorder, inorder)).toEqual(expected);
  });

  xtest('Reject traversals of different length', () => {
    const preorder = ['a', 'b'];
    const inorder = ['b', 'a', 'r'];
    expect(() => {
      treeFromTraversals(preorder, inorder);
    }).toThrow(new Error('traversals must have the same length'));
  });

  xtest('Reject inconsistent traversals of same length', () => {
    const preorder = ['x', 'y', 'z'];
    const inorder = ['a', 'b', 'c'];
    expect(() => {
      treeFromTraversals(preorder, inorder);
    }).toThrow(new Error('traversals must have the same elements'));
  });

  xtest('Reject traversals with repeated items', () => {
    const preorder = ['a', 'b', 'a'];
    const inorder = ['b', 'a', 'a'];
    expect(() => {
      treeFromTraversals(preorder, inorder);
    }).toThrow(new Error('traversals must contain unique items'));
  });

  xtest('A degenerate binary tree', () => {
    const preorder = ['a', 'b', 'c', 'd'];
    const inorder = ['d', 'c', 'b', 'a'];
    const expected = {
      value: 'a',
      left: {
        value: 'b',
        left: {
          value: 'c',
          left: {
            value: 'd',
            left: {},
            right: {},
          },
          right: {},
        },
        right: {},
      },
      right: {},
    };
    expect(treeFromTraversals(preorder, inorder)).toEqual(expected);
  });

  xtest('Another degenerate binary tree', () => {
    const preorder = ['a', 'b', 'c', 'd'];
    const inorder = ['a', 'b', 'c', 'd'];
    const expected = {
      value: 'a',
      left: {},
      right: {
        value: 'b',
        left: {},
        right: {
          value: 'c',
          left: {},
          right: {
            value: 'd',
            left: {},
            right: {},
          },
        },
      },
    };
    expect(treeFromTraversals(preorder, inorder)).toEqual(expected);
  });

  xtest('Tree with many more items', () => {
    const preorder = ['a', 'b', 'd', 'g', 'h', 'c', 'e', 'f', 'i'];
    const inorder = ['g', 'd', 'h', 'b', 'a', 'e', 'c', 'i', 'f'];
    const expected = {
      value: 'a',
      left: {
        value: 'b',
        left: {
          value: 'd',
          left: {
            value: 'g',
            left: {},
            right: {},
          },
          right: {
            value: 'h',
            left: {},
            right: {},
          },
        },
        right: {},
      },
      right: {
        value: 'c',
        left: {
          value: 'e',
          left: {},
          right: {},
        },
        right: {
          value: 'f',
          left: {
            value: 'i',
            left: {},
            right: {},
          },
          right: {},
        },
      },
    };
    expect(treeFromTraversals(preorder, inorder)).toEqual(expected);
  });
});

