import { describe, expect, test, xtest } from '@jest/globals';
import { Series } from './series';

describe('Series', () => {
  test('slices of one from one', () => {
    expect(new Series('1').slices(1)).toEqual([[1]]);
  });

  xtest('slices of one from two', () => {
    expect(new Series('12').slices(1)).toEqual([[1], [2]]);
  });

  xtest('slices of two', () => {
    expect(new Series('35').slices(2)).toEqual([[3, 5]]);
  });

  xtest('slices of two overlap', () => {
    expect(new Series('9142').slices(2)).toEqual([
      [9, 1],
      [1, 4],
      [4, 2],
    ]);
  });

  xtest('slices can include duplicates', () => {
    expect(new Series('777777').slices(3)).toEqual([
      [7, 7, 7],
      [7, 7, 7],
      [7, 7, 7],
      [7, 7, 7],
    ]);
  });

  xtest('slices of long series', () => {
    expect(new Series('918493904243').slices(5)).toEqual([
      [9, 1, 8, 4, 9],
      [1, 8, 4, 9, 3],
      [8, 4, 9, 3, 9],
      [4, 9, 3, 9, 0],
      [9, 3, 9, 0, 4],
      [3, 9, 0, 4, 2],
      [9, 0, 4, 2, 4],
      [0, 4, 2, 4, 3],
    ]);
  });

  xtest('slice length is too large', () => {
    expect(() => {
      new Series('12345').slices(6);
    }).toThrow(new Error('slice length cannot be greater than series length'));
  });

  xtest('slice length is way too large', () => {
    expect(() => {
      new Series('12345').slices(42);
    }).toThrow(new Error('slice length cannot be greater than series length'));
  });

  xtest('slice length cannot be zero', () => {
    expect(() => {
      new Series('12345').slices(0);
    }).toThrow(new Error('slice length cannot be zero'));
  });

  xtest('slice length cannot be negative', () => {
    expect(() => {
      new Series('123').slices(-1);
    }).toThrow(new Error('slice length cannot be negative'));
  });

  xtest('empty series is invalid', () => {
    expect(() => {
      new Series('').slices(1);
    }).toThrow(new Error('series cannot be empty'));
  });
});

import { describe, expect, test, xtest } from '@jest/globals';
import { Cipher } from './simple-cipher';

describe('Random key cipher', () => {
  const cipher = new Cipher();

  test('can encode', () => {
    // Here we take advantage of the fact that plaintext of "aaa..."
    // outputs the key. This is a critical problem with shift ciphers, some
    // characters will always output the key verbatim.
    expect(cipher.encode('aaaaaaaaaa')).toEqual(cipher.key.substring(0, 10));
  });

  xtest('can decode', () => {
    expect(cipher.decode(cipher.key.substring(0, 10))).toEqual('aaaaaaaaaa');
  });

  xtest('is reversible', () => {
    // I.e., if you apply decode in a encoded result, you must see
    // the same plaintext encode parameter as a result of the decode method
    const plaintext = 'abcdefghij';
    expect(cipher.decode(cipher.encode(plaintext))).toEqual(plaintext);
  });

  xtest('key is made only of lowercase letters', () => {
    expect(cipher.key).toMatch(/^[a-z]+$/);
  });
});

describe('Substitution cipher', () => {
  const key = 'abcdefghij';
  const cipher = new Cipher(key);

  xtest('can encode', () => {
    expect(cipher.encode('aaaaaaaaaa')).toEqual('abcdefghij');
  });

  xtest('can decode', () => {
    expect(cipher.decode('abcdefghij')).toEqual('aaaaaaaaaa');
  });

  xtest('is reversible', () => {
    // I.e., if you apply decode in a encoded result, you must see
    // the same plaintext encode parameter as a result of the decode method
    expect(cipher.decode(cipher.encode('abcdefghij'))).toEqual('abcdefghij');
  });

  xtest('can double shift encode', () => {
    expect(new Cipher('iamapandabear').encode('iamapandabear')).toEqual(
      'qayaeaagaciai',
    );
  });

  xtest('can wrap on encode', () => {
    expect(cipher.encode('zzzzzzzzzz')).toEqual('zabcdefghi');
  });

  xtest('can wrap on decode', () => {
    expect(cipher.decode('zabcdefghi')).toEqual('zzzzzzzzzz');
  });

  xtest('can encode messages longer than the key', () => {
    expect(new Cipher('abc').encode('iamapandabear')).toEqual('iboaqcnecbfcr');
  });

  xtest('can decode messages longer than the key', () => {
    expect(new Cipher('abc').decode('iboaqcnecbfcr')).toEqual('iamapandabear');
  });
});

