    const expected =
      'Team                           | MP |  W |  D |  L |  P\n' +
      'Allegoric Alaskans             |  1 |  1 |  0 |  0 |  3\n' +
      'Blithering Badgers             |  1 |  0 |  0 |  1 |  0';
